"""Entry-specific editorial rewrites; source records and clinical claims stay fixed."""
import copy,hashlib,json,re
from pathlib import Path
HERE=Path(__file__).resolve().parent
original=json.loads((HERE/'head-input.json').read_text(encoding='utf-8'))
byid={e['id']:e for e in original['entries']}
updates={}
def put(eid,title,summary,plain,notes=None):
    e=byid[eid];fields=copy.deepcopy(e['fields'])
    def refs(t):return re.sub(r'@([0-9]+)',lambda m:'[@'+e['source_ids'][int(m.group(1))]+']',t)
    fields['plain']=refs(plain)
    # Keep publication years where the shorter wording would otherwise obscure them.
    if eid=='hair-003':fields['plain']=fields['plain'].replace('综述并不能','2025年综述并不能')
    if eid=='hair-007':fields['plain']=fields['plain'].replace('发束实验发现','2011年发束实验发现')
    if eid=='eyes-015':fields['plain']=fields['plain'].replace('长期高频、干眼较重','中国2024共识也支持长期高频使用者相应选择；长期高频、干眼较重')
    if notes is not None:fields['notes']=refs(notes)
    updates[eid]=dict(id=eid,title=title,summary=summary,fields=fields)

put('hair-001','头皮油脏了就洗，干涩发尾另用护发素',
'洗发频率由头皮出油、出汗和残留决定，不必硬撑几天才洗。洗发水主要清洁头皮，护发素处理干涩发段；直发油头可洗得勤一些，干燥卷发按需要调整。持续红痛、渗出或掉发，改查原因。',
'头皮需要洗去油污，发尾可能同时需要润滑；两者不用同一种力度处理。油性直发可按需要每天洗，干燥卷发可以少洗些，没有人人适用的固定间隔。@0\n\n洗时把洗发水送到头皮，轻柔清洁；冲洗时带走发长残留，不把长发堆起反复搓。护发素用在需要的发长或发尾，洗后能清爽、好梳即可。@0@1\n\n不必再叠头皮磨砂、清洁泥等步骤。洗护已温和，仍有明显痒痛、结痂、渗出或持续掉发，就检查病因，而不是继续加大清洁。')
put('hair-002','头屑反复就选去屑成分，红痛掉发及时检查',
'轻度头屑可先规律洗发，仍反复再选酮康唑、二硫化硒等对应产品。把洗剂用在头皮，频率和停留按具体标签；红痛、脓包、斑片掉发或用后不改善，应检查，别靠抠洗或长期叠激素解决。',
'头屑不只是没洗干净，也可能伴有脂溢性皮炎等炎症。酮康唑、二硫化硒侧重相关微生物因素，水杨酸侧重去除鳞屑，不能只按“去油多强”选。@0\n\n轻度头屑先规律洗发；仍反复时，按标签把去屑产品用在头皮、留够作用时间。酮康唑指导常以2至4周看初始效果，之后可能低频维护；浓度、频率和分钟数仍按手中制剂。复发也不自动代表耐药。@1@2\n\n不要用指甲抠掉全部皮屑。红痛、肿胀、脓液、斑片掉发或规范使用仍无改善时就诊，不长期自行用激素复方；刚换产品后灼痒也需考虑接触反应。@2@3')
put('hair-003','选洗发水看洗后表现，不为“无硅油”盲目加价',
'含硅不自动伤头皮，无硅也不保证蓬松；氨基酸、无硫酸盐几个字同样不能保证整瓶温和。能洗净、头皮舒服、发丝易梳，就是实用判断。细软发压塌时，先减调理品用量或换轻配方。',
'洗发水的表面活性剂帮助油污被水洗走，调理成分负责顺滑和减少静电。“氨基酸”“无硫酸盐”只说明部分配方信息，不能单独代表清洁力或耐受。\n\n硅类如聚二甲基硅氧烷能润滑发丝，也可能在特定配方中沉积。综述并不能据此证明含硅就堵毛囊、无硅就更蓬松；发丝顺滑与毛囊生长也是两回事。@0\n\n按自己的问题选：细软发油塌就减量或换轻配方；漂染、卷曲、易打结则可能更需要调理。现有产品洗得净、用着舒服，不必为了换标签整套重买。持续刺激时查具体产品和反应。@1')
put('hair-004','发尾打结先用护发素，发膜按需要再加',
'护发素用来减少发丝摩擦、方便梳理，头皮油也不必省掉发尾护理。先试冲洗型，仍毛躁再少量加免洗品。发膜不一定比普通护发素更好；不要把冲洗型兑水当免洗喷雾，也别一口气叠满整套。',
'护发素主要润滑发丝、降低梳理阻力。发膜、免洗乳是不同配方或用法，名字“深层”不代表一定更有效。@0@1\n\n细软直发先把冲洗型用在发尾，干燥卷发可按需要照顾发长；停留和冲净按产品说明。洗后仍打结，再少量试免洗乳或喷雾，用到能梳开即可。冲洗型与免洗型不能互换，不自行兑水装瓶长期留发。@0@1\n\n一次只改一个步骤，比较是否更好梳、会不会压塌。普通护发素已够用，就不必再叠发膜和精油；持续断裂、裸露或恶化要检查，而不是不断加厚护理。')
put('hair-005','护发油少量涂发段，“深海胶囊”不等于生发药',
'护发油和打开后外涂的胶囊，主要按顺滑、光泽与解结效果判断。海洋名称、精油或维生素包装不能证明生发。看清冲洗还是免洗，从干涩发段少量试；压塌就减量，红痒就停，别靠发热香味判断有效。',
'护发胶囊是打开后外涂的发用品，不是口服营养剂。里面可能是硅类、植物油等调理成分；一粒包装或“深海”名称不能证明更能修复、更能生发。@0\n\n它们可以让发段好梳、发亮，这种收益不等于毛囊长出更多头发。按说明少量用于干涩处；细软发油塌就减量、缩小范围或换轻配方，不因立刻变亮就涂到头皮当生发液。@1\n\n“精油”商品名也不保证天然、不过敏。香料或植物成分可引起反应，有敏感史就查成分，持续红痒停用。只将允许接触头皮的制剂用于头皮。@2')
put('hair-006','漂烫后难梳易断，再考虑键合修护产品',
'键合修护研究看到过特定产品改善受损发束的表现，但不是长期真人疗效证明。先减少漂烫和热损伤、做好基础护发，再按梳理与断发变化试具体产品。焗油变顺、生发和永久恢复原样，是不同承诺。',
'“键合修护”针对发纤维中的化学连接；焗油则可能只是一种加热护理方式，两者不能因名称相近而混为一谈。\n\n2024年实验用9束漂白头发、每条件3束，比较特定K18与Olaplex产品单次处理。部分外观、显微结构与物性有变化，但不是9个人的试验，也没证明多次洗后仍有效；研究有企业合作资助。@0\n\n先减少继续漂烫和高温，普通调理仍不够再试。可从少量或单次服务比较：是否易梳、断发有无减少、洗后效果是否保留。不为“重建核心”预付长疗程，也不拿发丝处理治疗脱发。')
put('hair-007','吹头发用低中温并移动风口，烫痛就停',
'先轻轻吸去滴水，再用低中温、保持距离并移动风口，避免同一处一直烘。热损伤取决于温度、时间和重复次数，不是只有吹干或自然干两种绝对答案。热保护品不能许可任意高温，负离子标签也不能证明生发。',
'吹风、夹板和卷发棒都增加热暴露，温度以外，距离、持续时间和次数也影响损伤。发束实验发现热烘与自然干燥可出现不同结构变化，不能简化为某一种永远最好。@2\n\n先用毛巾轻包吸水，不来回猛搓；吹时低或中温、留出距离、不断移动，夹板不反复追同一段。热保护品按对应用途使用，仍要减少过热。@0@1\n\n选机器看温控、风量和能否舒服吹干，“负离子”“胶原风”本身不是修复或生发证据。头皮烫痛或灼伤就停，不靠更热追求效率。')
put('hair-014','头发打结从发梢梳开，不用凑够一百下',
'梳头是为了解结和造型，不是生发任务。把头发分小束，从发梢慢慢往上理，必要时借护发素增加滑感；直发可稍干后梳，紧卷发常在湿润带调理品时更好处理。别硬拉、反复刷或强梳定型后的硬发。',
'梳理能理顺发丝，没有规定每天梳一百下就会生发。湿发是否适合梳也看发质，不能一概禁梳或强求干梳。@0@1\n\n分成小束，从发梢少量理开，再往上；用宽齿梳或合适调理品减少硬拽。直发可稍干后轻梳，紧卷发常在湿润、带护发素时更容易解结。定型很硬时不强行拉梳。@0@1\n\n断发不全等于毛囊脱发；但持续疼痛、发际线稀疏或大量掉发，仍要查原因，不能只换美容梳。')
put('hair-008','细软发易塌先减残留，再少量用蓬松造型品',
'先看头发是油了才塌，还是用了厚重护理后就贴头。洗去残留、减少免洗品，再按需要少量试蓬松造型。剪裁和分缝也能修饰外观，但分缝持续变宽需查脱发；不要每天靠烫根、倒梳和高温硬撑发量。',
'“蓬松”主要是外观效果，不等于新增毛囊。先分辨刚洗也塌、下午出油才塌，还是调理后压塌，才能选对调整。@0\n\n按需洗去油污和残留，细软发把免洗护理改轻、减量，只照顾需要的发段。要造型时少量试适合发质的产品，干洗仅临时吸油，仍需水洗；粘硬后不要强行拉梳。@0@1@2\n\n剪裁、分缝可按个人偏好调整；持续变稀就查原因，不靠造型盖住进展。造型后红痒灼热停用，也别把每天高温、倒梳、烫根当必需护理。')
put('hair-009','干洗喷雾只能临时吸油，用后仍要水洗',
'干洗粉吸油、改善外观，却不会像水洗那样带走污物和残留。赶时间可少量用于油的位置，用过一两次后恢复正常清洗。不要整头反复厚喷或用食用粉自配；痒痛灼热就停，防火与通风按包装执行。',
'干洗喷雾靠颗粒吸附油脂，让头发看起来不那么油，不能替代洗发水加水清洁。@0\n\n赶时间或短时维持造型，可以按发色、发质和说明少量用在油处，等待后分散、梳理。AAD提醒用过一两次后恢复水洗，洗掉残留；这不是超过一次就有毒的界线。@0\n\n不整头反复厚喷、不拿食用粉长期替代；发白、干硬就减量清洁。痒、烧灼、触痛先停，停后仍不改善就检查，喷雾的防火、吸入和通风要求按包装做。')
put('hair-011','白发可保留或染色，别靠拔除和乌发补剂控制',
'几根白发不直接证明缺营养，想遮盖可以按喜好染色。反复拔会伤害局部头发，也不会阻止新白发。突然明显变白或伴其他异常再查原因；染发的天然、植物标签不保证不过敏，既往没反应也不能放松使用要求。',
'白发与毛囊产生黑色素的变化有关，个体差异很大。少数白发、没有异常时可保留或遮盖，不必直接认定营养缺乏；出现较早、变化明显或伴其他变化，可检查是否有可处理原因。@0\n\n遮白可选临时或持久染色，按颜色、补色频率和耐受取舍，收益是外观。反复拔白发可能造成稀疏，长出的仍可能白；乌发补剂也不能凭名称承诺复黑。@0\n\n“植物”“天然”不保证不过敏。按当前产品说明测试、使用；有染发反应史先查诱因，不轮流试大量产品。家庭标签测试不同于皮肤科查过敏原的斑贴试验。@1@2')
put('hair-012','头皮红痒破损时先不染烫，明显反应立即停做',
'染烫前确认头皮完好、材料与操作要求清楚，不靠延时上色，也不用家用染发剂染眉睫。漂染烫拉直不宜一次叠满；部分加热顺直配方有甲醛风险。灼痛红疹就停，肿胀伴呼吸吞咽困难等表现立即求助。',
'染烫既可能损伤发丝，也可能引起刺激或过敏；有些加热顺直配方可释放甲醛，不能由“角蛋白护理”四个字判断安全。@1@3\n\n头皮红痒、晒伤、破损时先不做。按标签测试、戴手套、控制停留并充分冲洗，不为加深颜色延时，也不改染眉睫；测试没反应仍不保证正式使用不过敏。多项化学服务按产品和发质安排间隔，不指望焗油抵消叠加损伤。@0@3\n\n明显灼痛、红疹或眼鼻刺激就停做，按产品要求洗去；脸或口咽肿胀伴喘、呼吸吞咽困难或晕厥，立即求助。保留包装照片供评估，不再试染证明耐受。@2')
put('hair-013','游泳后及时洗护，户外也给头皮遮阳',
'泳帽可减少接触，但不保证完全不进水；泳后及时冲洗、洗去残留并调理，比层层喷护理更实用。普通洗护已够用，不必另买游泳全套。户外遮住头发与暴露头皮，发用光泽油不能代替皮肤防晒。',
'泳池暴露、出水后摩擦和日晒，都可能增加发丝护理负担。泳帽是可选防护，不能保证一滴水不进。@0@1\n\n泳后及时冲洗、洗去残留，按发质调理；漂染或干涩头发尤其不要硬拉猛搓。普通洗护能洗净、发丝不粗涩，就不必只因偶尔游泳另买专用品；残留明显时再按问题选。@0@1\n\n长时间户外戴帽遮挡，发量稀少或分缝暴露处也需防晒。发丝光泽不代表头皮已获得足量防晒；眼睛和隐形眼镜另按[游泳护理](#/entry/eyes-017)处理。')
put('hair-022','扎发接发一拉就痛，立刻松开并减轻牵拉',
'紧扎和重接发可造成牵拉性脱发，疼痛不是造型必须付出的代价。先松、减重、换受力位置，别为了遮稀疏拉得更紧。调整后仍红痛、起包或变稀就检查；不靠精油按摩承诺已受损处一定能长回。',
'**发型拉得疼或刺，先松开。** 牵拉性脱发是毛囊反复受拉后出现掉发；持续紧扎、重接发可造成它，并不同于控制不住地拔毛。@0@1\n\n降低紧度和饰物重量，避免一直拉同一位置，并留出间歇。帽子本身不等于脱发，要看是否摩擦压迫、叠加紧扎；不为遮住边缘稀疏再拉紧剩余头发。@0@1\n\n仍持续变稀、红痛起包或出现光滑缺发区，就检查损伤与其他病因；能否恢复取决于病程。若反复拔毛难以控制，也要说明，不只换洗护品。@1')
put('hair-015','突然秃一块或头皮红痛流脓，尽快就诊',
'突然出现秃发斑，或掉发处红肿、疼痛、渗液、流脓，不能只买生发液。斑秃、感染和其他炎症外观可能相似，需要检查。候诊时别抠挤按摩，不共用梳巾；头癣常需处方药，普通去屑洗剂替代不了。',
'**突然秃一块，或掉发处灼热、压痛、红肿、渗液、流脓，要尽快检查。** 圆片状不一定是斑秃；感染、其他炎症及可能留瘢痕的疾病也需鉴别。@0\n\n医生会按表现选择头皮放大观察、真菌取样等，不是每人同一瓶生发液。头癣就是头皮真菌感染，通常需处方抗真菌片剂配合洗剂，普通去屑产品不能替代。疑似感染时不共用梳巾，不自行以激素万能止痒。@1\n\n候诊时停抠挤、针挑、强按摩，留下发作照片和用药记录；是否观察要在弄清病因后决定，不照搬别人自愈经历。@2@0')
put('hair-010','掉发明显增多就记录变化，再查原因选治疗',
'掉得多、密度降低和发丝折断不是一回事，每天数根数不能确诊。用相同角度和光线拍照，记录生病、手术、分娩、节食及用药变化，带去皮肤科。先分病因，再选择等待、护理或药物，不用养发套餐代替检查。',
'掉得多、整头变稀和发丝中段断裂，需要分别判断；洗发间隔与发长也会改变眼前那一团的大小，单数根数不够。@0@1\n\n用相同光线、分缝、角度拍照，记开始时间；就诊带近几个月生病发热、手术、分娩、明显减重、限制饮食和药物变化。医生按头皮与分布决定放大观察、抽血或取样，不是人人都查一套激素微量元素，也不要自行停原药。@0\n\n突然成片或伴红痛脓液看[异常掉发](#/entry/hair-015)；长期额角、头顶、发缝变稀看[逐渐型脱发](#/entry/hair-016)。明确原因才决定恢复观察、减牵拉或用药；影响社交情绪也值得说明。@2')
put('hair-016','发缝额角逐渐变稀，确认脱发类型再定长期方案',
'发缝越来越宽、额角或头顶持续变稀，可能是毛囊逐渐细软化的模式性脱发，不全因熬夜或缺营养。确认后按性别、孕哺计划和耐受讨论药物，也可以选择剪裁、遮盖或假发；护发素变顺不代表毛量恢复。',
'雄激素性脱发也叫男性型或女性型脱发，涉及遗传和毛囊逐渐细软化，不等于每个人血中雄激素都高。男性常见额角、头顶变稀，女性常见发缝加宽；其他病因也可能并存。@0@1\n\n确认后，男女可按适用性讨论外用米诺地尔，部分成年男性可考虑非那雄胺；女性不照搬男性方案，备孕、孕哺需另核。先定观察指标、复评时间和能否坚持，再考虑设备或手术。@1@2\n\n不想治疗也可剪裁、遮盖或用假发；想改善不必等大片秃发。药物细节看[米诺地尔](#/entry/hair-017)、[非那雄胺](#/entry/hair-018)；突然斑片、红痛流脓另走异常分流。@2')
put('hair-017','米诺地尔按制剂涂头皮，用数月后复评效果',
'外用米诺地尔可帮助部分已明确原因的脱发，需要数月评估和持续维持，不靠加量求快。按具体制剂涂头皮并洗手，刺激持续就复评；备孕孕哺避免使用。心悸、胸痛、明显晕眩或水肿要停用求助，不能都当正常适应。',
'米诺地尔是促进毛发生长的药，不是护发油。部分逐渐型脱发可获益，女性型脱发综述支持相对安慰剂的改善，但不保证恢复原密度。先确认原因，头皮红痛破损时不要直接上药。@0\n\n按具体浓度、剂型和说明涂到头皮，洗手、避眼及其他部位，不加倍求快。液体刺激可讨论配方或剂型，先排除头皮病，不硬扛红痒。@1\n\n拍基线并阶段复评；见效常需数月，全面判断可能需6至12个月，标签要求更早复评就照做。初期可暂时掉得更多，有效后需持续维持。备孕孕哺避免使用；胸痛、心悸、明显晕眩、手脚肿时停用及时求助。@2@3@1')
put('hair-018','男性脱发用非那雄胺，同时留意性功能和情绪',
'非那雄胺可改善部分成年男性的逐渐型脱发，但需要长期权衡收益和风险。开始前说明性功能、情绪病史和用药，出现变化及时复评；脱发用量下出现抑郁或自杀想法，应停药求助。女性不照搬，妊娠者还应避开破损药片。',
'非那雄胺抑制睾酮转成双氢睾酮的相关酶，减轻对易感毛囊的作用。随机试验支持部分成年男性获益，需要维护，不是一疗程根治。@0@1\n\n2025 EMA及2026 MHRA复核要求关注情绪、性功能；部分性功能症状可能停药后持续，不能保证立刻恢复。开始前说明相关病史、生育困扰和用药；脱发用1mg片出现情绪变化、抑郁或自杀想法，要停药并尽快求助，有立即自伤风险就紧急求助。@2@3\n\n女性不自行套用，妊娠或可能妊娠者避开破损药片。外用复配也可能吸收或造成他人接触，不能按“只外涂”保证零全身风险；地区和具体制剂另核。@1@4')
put('hair-019','口服米诺地尔须评估监测，不自行切降压药生发',
'口服米诺地尔是可讨论的处方路径，不一定比外用更好。外用不耐受或难坚持时，带心血管病史、血压和用药讨论；研究未显示优效不能说成已证明等效。多毛、头痛、水肿及心血管不适要留意，别照网帖切片叠药。',
'米诺地尔原本可作降压药，低剂量用于脱发的研究增加了，但口服与外用风险不同，仍需处方评估和监测。外用难坚持时，先查使用方式、配方和头皮问题。@0\n\n90名成年男性、24周随机试验未在主要结局显示口服优于外用；这不是严格等效证明，也不能推广所有性别与剂量。口服组可有多毛、头痛、下肢水肿。@1\n\n带心血管病史、血压及完整药单，约好随访和异常处理。备孕孕哺先说明，服药中怀孕及时联系处方者；胸痛、呼吸困难、明显心悸及时求助。不自行切片、叠加外用或停换原降压药。@0@2')
put('hair-020','掉发先查真实营养缺口，别直接买生发软糖',
'掉发不自动等于缺铁、锌或生物素。先看节食、体重和饮食线索，有需要再检查补充；营养够了，额外多吃不等于多长头发。生物素还会干扰部分化验，抽血前主动报产品和用量，不照网帖统一停几天。',
'营养缺乏可以影响头发，但补充只有针对真实缺口才有依据，不能由“头发需要营养”推出人人买软糖。生物素即维生素B7，支持其常规美容宣传的科学证据很少。@0@1@2\n\n先看长期限食、明显减重或已知缺乏，再按线索检查、补充；铁锌等边缘数值也不能独自解释全部掉发，既有缺乏治疗按原方案。@0@1\n\n生物素可能干扰部分心脏标志物等化验。抽血前告知名称和用量，让医护与检验人员决定是否调整，不自行套固定停药天数。@3')
put('hair-021','生发帽和PRP可作附加选择，先看对应临床研究',
'光疗生发帽和PRP注射有一定人体研究，但效果、设备和方案差异大，不是普通红灯或任意套餐都能借用。先明确脱发类型，再问具体研究、维护要求和如何评价收益，不因毛囊激活等机制宣传签全年疗程。',
'低能量光疗用特定光照刺激；PRP把自体血液处理成富含血小板的部分，再注入头皮，两者不是同一治疗。@0@1\n\n2025正式刊出的光疗综述主要研究雄激素性脱发，部分显示密度改善，但设备方案与结果差异大。2024 PRP综述也有正向信号，偏倚与操作差异限制结论；它们不是头对头排名。@0@1\n\n先把诊断和能坚持的方案安排好，仍想附加时，再问这台设备或这套操作是否对应研究、如何维护和复评。只给放大照片、拿不出资料就先不买，红痛或突然掉发则先检查。')
put('hair-023','植发先评估供区和脱发进展，别只按毛囊数下单',
'植发是把有限的健康毛发移到稀疏处，不会创造无限供发或阻止所有后续脱发。咨询时查供区、病因、恢复和瘢痕风险，谈清周围头发继续变稀怎么办；年轻且变化快时可能先治疗。报价先分清毛囊数与头发根数。',
'植发把供区健康毛发移到稀疏处，改善的是分布和外观，先要有足够供发和合适的受区。年轻、仍进展者可能需先治疗再评估。@0\n\n方案要讲清目标区域、密度、发际线、取发方式、恢复、瘢痕和后续维护，不只比“种多少”。供区有限，满头恢复未必现实；毛囊数与头发根数也是不同计价单位。@0@1\n\n周围原有毛发仍可能继续变稀，部分人需持续药物与复查，不凭刚做完的照片承诺长期效果。头皮有炎症或病因未明，先诊断处理。@2@0')

put('eyes-005','红眼怕光、突然看不清或眼前黑幕，立即就医',
'红眼伴怕光或视力突变，以及突然大量飞蚊、闪光、黑幕，即使不痛也要立即检查。戴隐形后红眼先摘镜并尽快联系眼科。化学品入眼马上用大量清水冲至少20分钟并求助；异物扎入不自行拔，视力异常不自己开车。',
'**红眼伴怕光、视力突然变化，立即去眼科急诊；突然大量新飞蚊、闪光或眼前黑幕，即使不痛也立即检查。** 这些变化可能涉及角膜或眼底，不能等它自行消失。@0@1\n\n戴隐形后发红，先摘镜并尽快联系眼科，不换新片继续戴。没戴隐形、仅轻微红且无痛无视力变化，可停揉眼观察；持续数天、反复或黏性分泌物多时检查。@0\n\n化学品入眼立刻以大量不烫清水冲至少20分钟，同时求助，别等买洗眼液；异物扎入不自行拔。日常隐形避水规则不适用于化学伤急救。视力异常请人陪同或呼叫急救，不自行驾车。@2')
put('eyes-013','眼睛总干却流泪，反复发作要查泪膜和眼睑',
'流泪多也可能有干眼：眼表泪膜留不住，仍会干涩。偶发不适先避风、完整眨眼、离屏休息，隐形不适改框架；需要时用人工泪液。反复影响生活或数周不改善，检查泪膜、角膜和睑板腺，别只换润眼产品。',
'干眼不只表现为“没眼泪”。眼表泪膜需要水分和眼睑腺体油脂配合，流泪多也不代表留得住；睫毛根结痂、眼皮红痒还提示眼睑问题。@2\n\n偶发屏幕后干涩、无红痛怕光或视力突变，可先避开风口、完整眨眼、插入离屏休息；隐形不适暂换框架，需要时从[人工泪液](#/entry/eyes-007)起步。@0@1\n\n反复影响工作或自护数周仍不好，检查泪膜稳定性、角膜损伤与睑板腺开口分泌，才能决定润滑、睑缘清洁或温敷等方案。伴口干、长期用药或近期手术时主动说明，不自行停处方。@3@0')
put('eyes-014','季节性眼痒流泪先避过敏原，不乱用抗生素激素',
'双眼每到某季节就痒、流泪并打喷嚏，值得排查过敏。先停揉眼和隐形、干净冷敷；已确诊而按原模式复发，可讨论对应抗过敏滴剂。首次发作、黏性分泌物多或持续不退要检查，明显痛怕光或视力变差走急诊。',
'结膜是眼白和眼皮内侧的薄膜，发生过敏性炎症时可双眼痒、流泪，常伴季节性喷嚏；但不能凭“痒”排除其他病因。@0\n\n确诊后按熟悉模式复发，奥洛他定、酮替芬等对应抗过敏滴剂比不断加润眼液更对题：它们抑制组胺作用，并稳定释放过敏介质的细胞。具体制剂按当地标签和医嘱。@1\n\n先停揉眼、停隐形，用干净冷毛巾轻敷。首次、黏性分泌物多或久不退检查；痛、怕光或视力变化走[急诊](#/entry/eyes-005)。不自用激素止痒；眼皮皮肤痒且换过眼妆、睫毛胶等，也要停可疑用品、查接触刺激。@2@0@3')
put('eyes-006','眼皮长针眼先温敷，不挤挑；久不退就检查',
'眼皮边红痛小包可能是麦粒肿，可用温热毛巾敷5—10分钟、每天2—4次，愈合前暂停隐形和眼妆。较硬不太痛的包可能是霰粒肿，不能仅凭图片分准。肿痛扩散、影响视力尽快检查，几周不退或同处反复也要复评。',
'麦粒肿俗称针眼，常是眼皮边红痛的小包；较硬、不太痛的也可能是腺体堵塞相关的霰粒肿，不能只凭一张图分准。@0@1\n\n可先用干净温热毛巾敷5—10分钟，每天2—4次；不挤、不挑、不自己拔睫毛，愈合前停隐形与眼妆。毛巾温敷时间不能照搬到电热或自发热眼罩。@0\n\n越来越肿痛、向周围扩散或影响视力时尽快检查；几周未退、同处反复长也要复评。引流等操作交给医护，不在家挤。@0@1')
put('eyes-023','突然看成两个影像要当天就医，头伤后直接急诊',
'突然重影或重影伴眼痛，需当天紧急评估；伴剧烈头痛、瞳孔异常扩大或头伤后出现，直接急诊。记录何时开始、看远看近及遮一眼的变化可帮助检查，但不能拿遮眼后变好排除急症，也别先买训练课或自行开车。',
'**突然重影，或同时眼痛，当天紧急评估；伴剧烈头痛、瞳孔异常扩大或头伤后出现，直接急诊。** 复视就是一个物体看成两个影像，不全因散光或疲劳。@0\n\n记录开始时间、远近差异、遮住一眼后是否消失。单眼仍重影与只有双眼同时看才重影，检查方向可不同；这是病史线索，不是家庭排除急症的测试，持续或间歇都需检查。@0\n\n治疗取决于屈光、眼表、双眼协同或其他病因，不先买眼罩、棱镜或训练课程。避免自行驾驶，突然视力下降或黑幕按[眼部急症](#/entry/eyes-005)处理。')
put('eyes-020','视力不等于近视度数，报告分三项看',
'视力0.5不是近视500度。视力记录看清视标的能力，度数来自验光，眼轴记录眼球前后长度，三者不能互相换算。保留左右眼结果、日期和当时眼镜；即使看得到1.0，也不能排除眼底、视野或双眼配合问题。',
'视力是分辨视标的能力，屈光度数是验光确定的镜片需求，眼轴是眼球前后长度。视力0.5不能推成近视500度；国内小数1.0对应五分5.0，0.5对应4.7，是视力的两种记录。@0@1\n\n再分清裸眼与戴镜：不戴矫正镜片的结果叫裸眼视力，戴镜结果须注明当时所用矫正。同度数可能不同视力，同视力也不能唯一决定处方。@2@3\n\n保留左右眼、日期、镜片与验光报告，在相同条件下比较。看得到1.0也不能排除眼底、视野或双眼协同问题；手机截图或随手打印受尺寸距离照明影响，不作严格比较。@4@5@0')
put('eyes-001','戴镜还看不清先查验光和眼睛，别急着升级镜片',
'近视、远视、散光需要合适矫正，戴镜仍眯眼模糊时应回查验光和眼部情况。先把处方、佩戴与使用任务配合好，再选厚度等附加项。少戴或故意低配不能当儿童控近视方案；突然模糊伴痛、闪光黑幕要急诊。',
'近视、远视和散光属于屈光不正，即光线没准确聚焦到眼底。眼镜先要矫正这个问题，附加功能多不代表基础矫正更准。@0\n\n戴镜仍眯眼、看远模糊，带旧镜验光并检查眼睛，核度数、散光和当前任务。处方佩戴合适后，再比重量、厚度或附加项。@0\n\n儿童少戴或故意欠矫不是已证实的控制方法，普通矫正与[近视控制](#/entry/eyes-008)分开决定。突然看不清伴痛、怕光、闪光或黑幕，直接[急诊](#/entry/eyes-005)。@1@2')
put('eyes-021','配镜带旧镜完整验光，不凭电脑小票直接下单',
'仪器小票只是验光的一部分，还要结合你比较镜片的结果、双眼与实际任务定处方。儿童初次或调节不稳定等情况可能需散瞳验光，年轻成人不是次次都必须做。检查后模糊怕光时安排陪同，不按别人恢复时间决定自己能开车。',
'客观验光用仪器或检影估计屈光状态，主观验光让你比较不同镜片，再结合双眼和用途定处方，所以电脑小票不等于最终答案。@0\n\n散瞳验光用药暂时放松看近时的聚焦调节，儿童初次、调节不稳或结果难解释时尤需评估；成人不必次次一律做，也不因怕伤眼拒绝确有指征的检查，用药前核禁忌。为观察眼底而散瞳则不等于配镜已完成。@0@1\n\n配镜带旧镜旧处方，说清远处、电脑或阅读哪里不适。散瞳后模糊、怕光时可带太阳镜并请人陪同，恢复且符合安全要求前不驾驶。@1')
put('eyes-022','配新镜看懂球镜散光和瞳距，小变化不必急换',
'SPH管球镜、CYL管散光量、AXIS管散光方向，不能只挑一个数字看。装配还要测瞳距等位置参数；旧镜清楚舒服，微小变化不一定马上换。换后持续头晕变形应回查，隐形眼镜也不能直接照搬框架度数。',
'处方中SPH是球镜，负号通常用于近视、正号用于远视；CYL是散光矫正量，AXIS是方向，需一起理解。近用附加或棱镜另按具体任务，不自行拼处方。@0\n\n瞳距是双眼瞳孔中心间距离，配装需让镜片位置对应眼睛；处方没写时由配装者补测，不靠照片估填。@1\n\n旧镜清楚舒服且满足任务，小改度数未必需立刻换，先问改善什么。新镜持续头晕、变形或不清要回查处方装配和眼睛；隐形还需基弧、材质等验配信息，不照抄框架度数。@1@2')
put('eyes-026','看近重影头痛先查双眼配合，再选视觉训练',
'看书重影、串行或头痛，不一定多加近视度数就好；集合不足等双眼配合问题也可能存在。先检查，再按测出的异常讨论训练或特定镜片。儿童部分训练证据较好，成人比较仍不清楚，不能拿儿童成功率承诺成人摘镜。',
'集合是看近时双眼协调向内转动，集合不足可让阅读重影、字飘或头痛；视力表看得清也可能有。先查屈光、眼表和双眼配合，必要时测集合近点与调节。@0\n\n确诊有症状后，可讨论专业安排的集合/调节训练，部分情境比较特定棱镜。2020综述对儿童部分诊室训练加家庭强化更支持，成人方案比较较不确定；缓解不适、改善指标与控制近视是不同结局。@0@1\n\n买串珠、软件、VR或课程前，问清对应哪项已测异常、如何复评，不为泛称“练眼肌”付费。突然新发复视先[及时就医](#/entry/eyes-023)。')
put('eyes-031','给孩子安排户外和用眼间歇，不只换护眼灯',
'户外时间要真正排进日常，连续近看既包括手机，也包括作业和读书。用20分钟看约6米外至少20秒作休息提醒即可，它不是保证防住近视的疗法。自然光不等于直视太阳；看不清仍需验光，已有近视按方案复查。',
'儿童户外较多与较低近视发生风险有关，近视也受遗传等影响；户外不能逆转已有近视，更不是直视太阳。护眼灯不能代替出门活动。@0@1\n\n把活动安排进课间、放学和周末；作业、阅读、屏幕都需打断连续近看。可用每20分钟看约6米外至少20秒作舒适用眼提醒，不把节拍当已证实的近视控制处方。屏幕略低、避反光、字太小先放大。@2\n\n镜片要分矫正、减少反光与有直接研究的近视控制用途，不能用防蓝光标签代替。眯眼、黑板不清或头痛应[检查](#/entry/eyes-032)，户外与间歇不替代筛查复诊。@1@2')
put('eyes-032','孩子看不清先验光，配镜与控近视分开决定',
'眯眼看黑板或学校筛查异常，应做儿童眼科和验光检查，必要时散瞳；筛查不是诊断。眼镜先让孩子看清，再根据度数、眼轴和进展讨论控制。选戴得稳、不压痛的镜架，戴法复查按处方，不靠少戴或低配防加深。',
'学校筛查用来找可能的问题，不是完整诊断。孩子眯眼、黑板不清，不能直接认定近视，应预约有儿童验光能力的正规机构；必要时用散瞳验光暂放松调节。@0@1\n\n确诊后分清两个目标：矫正让课堂与活动看得清，近视控制则尝试减慢进展。眼轴是眼球前后长度，不能由视力分数换算。普通框架、控制框架、特殊软镜和OK镜用途护理不同，见[镜片选择](#/entry/eyes-008)，也不靠欠矫控制。@0@1@2\n\n选稳、不压痛的镜架，运动另作防护。戴法和复查按处方、实际任务决定，不套“越少戴越好”；用接触镜也备框架，红痛或突然模糊提前检查。@0')
put('eyes-024','成年后度数仍加深，带历次处方查真实变化',
'成年不代表近视必然稳定，单次电脑验光变化也不证明眼轴在增长。带旧镜和历次报告复查，确认后记录度数、眼轴和时间；不能把儿童控制试验当成人同样有效。突然下降、单眼明显变化或疼痛要另行检查。',
'青年成人仍可新发或加深近视，不能只因成年就排除；一次仪器读数也不能证明进展，需重复验光与眼部检查。@0\n\n确认变化后，记录屈光度、眼轴和日期，讨论监测频率，尤其高度近视、近期变得明显或计划手术者。眼轴是补充信息，不是一测就能诊断全部风险。@0\n\n2023成人综述提示大型控制研究仍不足，儿童离焦片、OK镜、阿托品资料不能直接当成人疗效保证。先确认进展与目标；休息照顾舒适，不承诺降回度数。突然或单眼明显下降、疼痛另走检查路径。@0')
put('eyes-025','近视较深要随访眼底，看得清也不能省',
'高度近视通常指约600度及以上，但度数不是眼底检查的唯一门槛。戴镜清楚、度数稳定或摘镜手术成功，都不代表眼底风险消失。按症状和既往情况安排检查随访；新飞蚊闪光、黑幕或明显变形，别等常规复诊。',
'高度近视通常约600度及以上，与某些眼底问题风险有关；度数不是唯一界线，戴镜看清也不能代替眼底评估。国家2026指南对较高度数或相关眼底改变提出监测要求。@0@1\n\n按症状、既往记录和风险决定是否散瞳及复查频率，说明家族病史、裂孔或眼病；不套其他风险组的统一套餐，也不靠一次照相正常保证以后安全。@2\n\n新飞蚊大量增加、闪光、黑幕或明显变形，及时[急诊检查](#/entry/eyes-005)。激光、植入镜片主要改变矫正方式，术后也保留眼底跟踪；病理性近视还需看结构，不凭度数自诊。@1')
put('eyes-030','“恢复视力”先问改变了什么，不凭多认两行付费',
'少疲劳、裸眼多认两行、近视度数改变和眼轴变化，是不同结果。眼贴、按摩或短期训练不能凭一次视力表照片证明治愈近视。确有集合不足等问题可作针对治疗，但先问诊断、对照、结局和随访，而不是听通用摘镜承诺。',
'“视力改善”可能只是当时多认几行，也可能指戴镜清晰、症状缓解或长期度数变化。测量还受距离、照明和矫正影响，不能互换成眼轴逆转或近视治愈。@0\n\n眼保健操等涉及调节和疲劳任务，不等于任意眼贴、按摩器都有控制近视证据。儿童控制要看对应治疗研究，成人证据另核。@1@2\n\n也不一概否定视觉训练：[集合不足](#/entry/eyes-026)等明确问题有特定路径，改善它不等于治愈轴性近视。购买前问诊断、人群、对照、结局和随访，不只看前后照片。@3@4')
put('eyes-002','屏幕后干涩先完整眨眼、离屏休息并避风',
'完整眨眼有助泪液铺开，连续近看时安排看远和离屏休息，别让空调直吹。字太小就放大，屏幕略低于视线；隐形不舒服可缩短佩戴改框架。休息提醒不是精确药量，反复影响工作应查眼表和矫正。',
'完整眨眼帮助泪液铺到眼表，连续近看与直吹风可能加重干涩；处理环境是干眼护理的一部分。@0@1\n\n休息时完整闭眼再睁，穿插看远和离屏，移开风口。屏幕略低于眼平，文字放大到不用眯眼；仍不清楚就核矫正。@1@2\n\n提醒软件可帮记得休息，不必把间隔当药物剂量。隐形才不适就缩短佩戴、改框架；休息后仍反复影响工作，走[眼表检查](#/entry/eyes-013)，不只改倒计时。')

put('eyes-007','眼干先选人工泪液，夜间不适再比较凝胶眼膏',
'人工泪液是润滑滴剂，普通干涩可先选一款耐受的水样配方，不按清凉去红挑。凝胶眼膏留得久，也易暂时模糊，夜间不适宜先评估；油腺异常还需眼睑护理。反复依赖滴剂时复查，不只买更黏的。',
'人工泪液是润滑眼表的滴剂，常见玻璃酸钠、羧甲基纤维素、聚乙二醇等。轻度干涩可从一款适用耐受的水样配方起步，不必叠多瓶。@0@1\n\n白天看屏或开车需留意模糊；夜间或清晨仍不够，可检查后讨论更持久、也更易暂时模糊的凝胶眼膏，常安排睡前。睑板腺油脂异常还可能需含脂质润滑和眼睑护理，不能只加补水。@0@2\n\n长期反复需要，复评眼表并看[防腐体系](#/entry/eyes-015)，夜间不适也不自动等于重度。去红药不是升级版，含四氢唑啉等过度用可加红；新用品后痛或视力变差应停用并[及时就医](#/entry/eyes-005)。@3@4@5')
put('eyes-015','频繁滴人工泪液或易刺激，优先比较无防腐剂',
'防腐剂防污染，是否避开要看使用频率和眼表耐受。偶尔用且舒服，不必一律换；频繁依赖、干眼较重或明显刺激，可优先无防腐剂并复评。氧化型仍是防腐体系，戴隐形可用与否、开封弃置仍要看具体标签。',
'防腐剂用于抑制污染；氧化型、可分解型也属于防腐体系，不能改称无防腐剂。@3\n\n偶尔用正规润滑剂且耐受，不必仅为含防腐剂换掉。长期高频、干眼较重或刺激明显，可优先无防腐剂并复评；每日超过4次是常见选配提醒，不是第5次开始有毒。直接比较也未证明所有人换后都更有效。@0@1@4\n\n戴隐形时须另核允许性，无防腐剂标签本身不够。洗手、瓶口不碰眼，开封弃置按包装；处方眼药不自行替换，镜片双氧水消毒液不能滴眼。@2@5@6')
put('eyes-016','过敏肿痒用冷敷，睑板腺护理再考虑温敷',
'冷敷与温敷用途不同：过敏肿痒可用干净冷毛巾，已确认油腺问题才把温敷纳入护理。温毛巾、可加热眼罩、一次性蒸汽罩按方便和维护选择，额外震动气压不自动更有效。先摘隐形、烫痛就停，不自行按眼球。',
'睑板腺是眼皮内供油的腺体，其异常可纳入温敷护理；过敏性肿痒则可先用干净冷毛巾。不是所有干涩都靠加热。@0@1\n\n温敷研究支持合适情境下的部分症状和泪膜改善，但用品方案不同，不能借给任意按摩仪。温毛巾需重新温热，可重复眼罩需清洁加热，一次性罩省准备但有耗材；按自己能坚持的方式选。@1@2@3\n\n医院毛巾护理常约5—10分钟，加热用品仍按本品说明。摘隐形，烫痛就停，不为热感延时、不挤腺体或按眼球；按摩先让医护演示，痛怕光或突然模糊不靠眼罩拖延。@2@3')
put('eyes-003','屏幕看久眼累，先别为防蓝光镜片加钱',
'防蓝光片能滤部分可见光，不代表临床上更护眼。综述对短期电脑疲劳未见明确优势，睡眠效果不确定，也缺长期黄斑保护资料。先把矫正、佩戴与干涩处理好；喜欢色调可为偏好选择，不把它当防病保证。',
'防蓝光镜片过滤部分短波可见光，过滤量本身不是眼疲劳改善的临床结果。@0\n\n2023年综述纳入17项随机试验，短期电脑疲劳未见明确优势，睡眠结果不确定；也没有相应长期黄斑保护试验。黄斑是眼底中央负责精细视觉的区域，不能仅凭滤光推导保护效果。@0\n\n为普通屏幕疲劳配镜，先把矫正、贴合与干涩处理好，不优先买此附加项；若喜欢色调可按偏好选，但别因此省掉检查和护理。')
put('eyes-004','只因看屏幕多，不必把叶黄素当必买护眼品',
'叶黄素的特定黄斑疾病配方，不能直接推荐给所有屏幕使用者。普通成人试验有部分检查指标改善，却未显示视觉疲劳自评更好。先解决眼干、看不清和佩戴不适；有黄斑病者按诊断选配方，吸烟史也要说明。',
'叶黄素、玉米黄质属于类胡萝卜素。广告常用的AREDS/AREDS2，是针对年龄相关黄斑变性的大型研究；特定疾病阶段的配方不等于健康人都该吃。@0\n\n2025年70名18—65岁高屏幕使用成人试验观察6个月，部分眼科指标改善，疲劳自评无组间优势；有效性分析60人、有产业资助，不能承诺明显少累。@1\n\n没有相应眼底疾病、只是看屏幕多，先处理干涩、矫正和佩戴，不把胶囊列必买。疾病患者按眼底诊断选，当前或既往吸烟者不使用含β胡萝卜素的旧AREDS配方。@0')
put('eyes-008','日常省心选框架，隐形和OK镜按场景与护理能力选',
'框架省去镜片接触角膜的护理，偶尔不戴框架可验配日抛；OK镜用夜间佩戴换白天便利，不能保证全天免镜。儿童还要把看清与控近视分开，有对应研究的控制镜片才值得比较；年龄合适也不替代角膜检查、家长护理和复查。',
'框架在眼前矫正光线；软镜接触角膜；OK镜用特制硬镜暂改角膜形状，通常夜戴昼摘并持续维护，不是治愈近视。@0@1@2\n\n成人日常省心先选合适框架；偶尔免框架，验配合适后先比较日抛；几乎每天戴，再比较日抛与复用的适配和护理。OK镜留给重视白天免镜、能夜间护理复查者，还要评估眩光与夜驾，备好备用矫正。会戴着睡、卫生条件不足、眼红、活动性过敏或明显干眼时，先用框架。验配查角膜、泪膜、眼睑和试戴贴合，不靠高透氧或价格补救。@0@3\n\n儿童分“矫正看清”和“减慢度数/眼轴增长”：普通单焦主要矫正；家庭难完成接触镜护理时，可先比较有对应研究的DIMS、HAL等控制框架，其小光学区域设计不同于防蓝光镀膜，不能只看“离焦”宣传。希望白天少戴镜再考虑OK；2026中国指南列8岁及以上，仍须角膜、卫生和监护合格。能规范日戴者，也可比较有控制研究的双焦/多焦软镜，普通软镜、美瞳不能替代。斜视、双眼功能异常、弱视等须先评估适用性。@4@5@6@7@8@9\n\n记录验光与眼轴基线，通常至少半年复查，不必等一年加深50度才讨论。OK初戴后第1天、1周、1月、3月复查，此后每3—6个月，红痛或视力异常提前；儿童需家长配合。白天看清不能单独证明近视控制。@4@5')
put('eyes-009','偶尔戴软镜优先比较日抛，复用片每次都要护理',
'日戴是睡前取下，日抛是一次丢弃，两者不能混。偶尔佩戴可用日抛省去镜盒消毒；经常戴再比较适配与护理负担。日抛不重复，月抛也不连戴一个月、不攒使用天数；所有选择都要验配、避水并睡前摘。',
'日戴说明睡前必须摘，日抛说明一次用完丢弃；月抛等说更换周期，不是允许睡戴，也不默认按累计佩戴天数计算。@1\n\n偶尔不戴框架，日抛通常省去长期镜盒和消毒液维护；几乎每天戴且能稳定护理，再比较日抛和复用的适配、参数及负担。都须先验配，不能为省钱跳过。@0\n\n复用每次取下都清洁消毒，按标签换新；日抛不重复用，所有日戴镜都不睡戴、不沾水。日抛只是减少护理环节，不保证零感染或各类风险按同一比例下降。@2@3@4@5')
put('eyes-010','美瞳先查注册并验配，零度数也要正规选择',
'美瞳包括零度数款都接触角膜，在中国按第三类医疗器械管理。先核注册、厂家、中文说明和来源，再验配，花色放后面。夹层色素不能一句话判毒或无毒；红痛怕光或模糊就摘镜就医，不共用也不换花色硬撑。',
'美瞳是改变外观的接触镜，零度数也接触角膜，在中国同样属第三类医疗器械。审美用途不需要包装成养角膜。@0\n\n“色素夹在两层中间”不能单独证明安全，有色素也不等于全部有毒；具体产品、适配、周期和护理更能改变实际选择。@0@1@2\n\n核包装注册号、生产信息和中文说明，到药监查询，留凭证，再完成验配。眼表炎症、明显过敏或不适先回框架；不共用，红痛怕光或视力异常摘镜后[及时就医](#/entry/eyes-005)，不换新片继续。@3@4')
put('eyes-027','激光摘镜先查适用性，再按恢复和生活需求选术式',
'激光改变角膜形状来减少眼镜依赖，不能只按全飞秒名称选。成年人还需度数稳定、角膜和眼表合格；怀孕哺乳等会影响时机。比较角膜瓣、恢复、干眼和夜间视觉，满意不代表没有新症状，付款前讲清风险与随访。',
'激光通过重塑角膜调整聚焦。中国2026指南提出18岁以上、度数稳定至少2年且每年变化不超过50度等条件，还需查角膜形态厚度、眼表和病史；孕哺、仍变化或明显干眼会改变时机。@0@1\n\nLASIK制瓣后处理，常被考虑于希望较快恢复者，但有撞击风险要问角膜瓣；SMILE取出角膜内薄片、避开角膜瓣，仍受适用条件限制；PRK等表层方案等上皮恢复，恢复较慢。按检查先排不适合者，不由“无瓣”推出零风险。@1@2\n\n说明职业、运动、夜驾、眩光容忍和干眼，先处理眼表。满意与新视觉症状可同时存在，不只看视力表或满意率；隐形停戴、恢复与并发症联系方案在付款前谈，按团队要求而非统一天数。@3@4')
put('eyes-028','考虑ICL先查眼内条件，“可取出”不等于完全可逆',
'ICL是在保留天然晶状体时，手术额外放进矫正镜片，不是可自行摘戴的隐形。高度数或不适合角膜激光者可评估，但还要查眼内空间、内皮、眼压眼底。感染、白内障、视觉干扰和再手术风险要一起考虑，术后仍随访。',
'有晶状体眼植入保留自己的天然晶状体，再放入矫正镜片；ICL是常见后房类型，取戴需要手术。高度数或角膜不适合激光可讨论，不自动代表更安全。@0@1\n\n除了屈光稳定，还查眼内空间、角膜内皮细胞、眼压眼底和病史。内皮维持角膜透明，前房是角膜后方眼内空间；太窄等情况影响适用，不能只按度数对型号。@2\n\n把感染、眼压变化、白内障、视觉干扰、再手术和长期跟踪一起衡量。“可取出”不保证原眼部状态或视力完全恢复。具体年龄度数核中国许可与说明书，不照搬外国标签。@0@1')
put('eyes-029','摘镜术后按方案滴药复查，疼痛视力变差提前就医',
'离院前拿到滴药、复查和联系方式，激光与眼内植入不能照抄同一恢复时间。别揉眼、擅自戴回隐形或未恢复就开车；严重痛、视力或症状越来越差，立即联系团队或眼科急诊。长期保留术前资料，摘镜不等于免掉眼健康随访。',
'激光角膜手术与眼内植入恢复要求不同；短期干涩波动可需处理，恶化则不能当正常恢复。@0\n\n离院前拿书面滴药、复查与联系方案。LASIK一般监管资料列24至48小时检查，实际节点按团队；不揉眼、不自戴普通隐形遮模糊，视力不稳不驾车。严重疼痛或视力症状越来越差立即联系，联系不上或有急症去眼科急诊。@0\n\n长期保留术式、术前度数和检查资料。角膜手术不保证眼轴停止增长；ICL也需随访，英国资料每年眼健康检查是维护参考，不替代早期或个人更密计划。@1@2')
put('eyes-011','日戴隐形睡前、洗澡和游泳前都摘下',
'普通日戴软镜不能因透氧高就戴着睡，午睡也要先摘；OK等专业夜戴方案另有要求。洗澡游泳先换框架或度数泳镜。碰水后尽快摘，一次性丢弃、复用按流程消毒；红痛怕光或模糊停戴就医，不换片继续。',
'普通日戴镜的设计不等于夜戴，透氧高也不许可睡觉；OK等专业夜戴使用另有适用条件和流程的镜片。@0@1@2\n\n把摘镜绑在固定动作：午睡、晚上睡、进浴室和下水前先摘；夜班后补觉也换备用框架。水上需矫正可选度数泳镜。@0@1\n\n意外碰水尽快摘：一次性丢掉，复用按适配清洁消毒后再考虑戴。红痛怕光或模糊先停并检查，不只换新片。化学品入眼仍立即冲洗求助，不能因戴镜耽误。@1@3')
put('eyes-012','隐形护理液每次用新液，双氧水必须完成中和',
'多功能液与双氧水是两套护理系统，都不能用清水唾液代替消毒。复用片按说明揉搓、冲洗并换全新液体，镜盒也要维护。双氧水必须配套盒并完成规定中和后才戴，未中和液不能滴眼或冲片后马上佩戴。',
'多功能护理液用于清洁消毒，双氧水系统则需中和后才能接触眼睛；润湿或冲洗液不自动有消毒能力。@0@1@2\n\n洗手擦干，按说明揉搓冲洗复用片，用全新液体浸泡，旧液倒掉不续杯；镜盒按对应系统清洁、晾干、更换，不用清水唾液代替。@0@1\n\n双氧水用配套盒，完成规定中和才戴，不改普通盒、不把未中和液滴眼或冲片后立即戴。时长和开封期按产品；流程总漏做，就比较[日抛](#/entry/eyes-009)，不把护理减步骤。红痛先摘镜就医。@2@3')
put('eyes-017','泳前摘隐形戴泳镜，泳后无不适不必滴抗生素',
'泳后红涩可能是化学刺激，不自动等于感染。健康人在规范泳池游泳、没有不适，不必常规滴抗生素消毒。下水前冲淋摘隐形、戴泳镜，出水洗手脸和眼周；轻干可润滑，疼痛怕光模糊或持续加重则检查。',
'泳池氯与汗污反应形成的氯胺等可刺激眼睛，红不自动等于细菌感染。一般健康读者规范泳池游后无不适，不必常规抗生素“消毒”。@0@1@2\n\n下水前冲淋、摘隐形、戴贴合泳镜；近视可用度数泳镜，不拿“隐形加泳镜”替代摘。出水清洁手脸眼周，不揉。@1@3@4\n\n轻干且无痛、怕光、视力变化时可按需人工泪液，它不杀菌。持续加重、分泌物增加要检查，痛怕光模糊走[急症](#/entry/eyes-005)；戴隐形后红眼先摘并尽快评估。术后眼病按个人医嘱，强清洁剂入眼另作立即冲洗急救。@3@5@6')
put('eyes-018','灰尘进眼别揉，冲后仍痛或模糊就检查',
'松散灰尘或睫毛可让泪液带出，或用清洁温和水流冲洗，不用手指棉签镊子找。冲后仍有异物感、疼痛或模糊就检查；隐形不适先摘。打磨钻孔的高速碎屑、东西扎入眼球，直接急诊，不自己拔或反复冲着试取。',
'**进灰先不揉、不挖。** 揉擦可能让异物擦伤角膜。轻微、低速灰尘睫毛可由自然泪液带出，或以清洁、不烫的水轻冲，避免强水流；不把手指棉签镊子伸到眼球找。@0@1\n\n冲后仍有异物感、疼痛或视力不清，尽快眼科检查；隐形出现异物感先摘停戴就医，不适未消失前停眼妆。@0@1\n\n高速打磨钻孔碎屑、东西扎入，直接急诊，不挑拔、不反复冲着尝试取出；明显痛、怕光、出血或视力变化也走[急症](#/entry/eyes-005)。急救用水不等于日常镜片可用自来水洗。@0@1')
put('eyes-019','眼妆不共用，干睫毛膏不兑水，车上不补妆',
'眼妆的价值是好看，卫生与操作决定一部分风险。化妆前洗手清洁工具，睫毛膏眼线不共用，干了不加水唾液。感染期暂停并丢弃当时用过的相关用品，刺激先停；有效期按具体产品，不统一硬定三个月，也不靠兑水延寿。',
'眼妆品污染、共用和兑水可能破坏原有卫生保护，晃动车辆里刷杆则可能直接伤眼。@0\n\n化妆前洗手，保持工具清洁；睫毛膏眼线不共用，干掉不加水或唾液。车在行驶、身体晃动时不补眼妆。@0\n\n眼感染期暂停，并丢弃感染时用过的相关用品；某产品刺激先停，持续不适检查。有效期、开封期按具体产品和状态，不统一设三个月，也不以兑水或共用省钱；痛怕光或视力变化及时就医。@0')

put('nose-001','鼻毛只剪露出的部分，不连根拔或蜜蜡清空',
'鼻毛帮助拦住颗粒，不需要为了干净全部去除。想整理就用专用修剪器或圆头剪，只处理露出部分，不往深处探。拔或蜜蜡可造成倒生毛感染；入口已红痛或结脓痂先停，反复加重时检查，不自己挤破。',
'鼻毛是鼻孔入口帮助拦颗粒的毛发，不是需要全部清空的污物。连根拔或蜜蜡牵拉毛囊，可引起倒生毛和感染。@0\n\n想整理外观，在光线好处看清，用专用修剪器或圆头小剪，只剪露出部分，不往深处伸；工具按说明清洁干燥。电动的价值是方便修短，不是杀菌增强过滤。@0\n\n入口红痛、肿或有脓痂就停，反复加重检查，不在家挤。偶尔拔过一根不代表必然严重感染，今后温和修剪即可。')
put('nose-002','鼻腔干痂先湿润，不抠挖或睡前往深处涂油',
'鼻腔干硬痂先用鼻用盐水喷雾湿润，只轻清够得着的软化部分；抠挖和用力擤会反复出血。喷雾湿润不等于人人需大水量洗鼻。润滑可比较鼻用水溶性品，长期深涂油有少见吸入风险；持续痒痛脓痂需检查。',
'鼻内表面干燥、被反复抠挖或猛擤，都可能结痂出血。盐水喷雾主要湿润，并不要求每天大水量冲洗。@0@1\n\n用鼻腔用途盐水先软化，只轻清容易够到的部分，不用指甲剥、深塞棉签镊子。正在流血就先[压迫止血](#/entry/nose-006)，不继续冲洗抠痂。@0@1\n\n长期鼻内深涂凡士林、矿物油等有罕见吸入肺的风险；需润滑可选鼻用水溶性产品，按说明少量。长期痒、常揉或一处反复疼痛脓痂，查原因，不增加清洁。@0')
put('nose-005','鼻痒喷嚏清涕反复，记录触发因素再选治疗',
'季节、打扫床铺或接触动物后鼻痒喷嚏清涕，尤其伴眼痒，值得查过敏。烟、香水、温差也可引起非过敏鼻炎，发热不适还需考虑感染。先记接触规律、减少已知触发，影响睡眠学习或药店方案无效时检查，不长期靠通鼻喷雾。',
'过敏性鼻炎是鼻内表面对过敏原的炎症反应，季节性鼻痒、喷嚏、清涕和眼痒提供线索；烟、香水、温差也可引起非过敏鼻炎，发热全身不适还要考虑感染，不能单凭鼻塞自定病名。@0@1@2\n\n记症状与接触的关系，减少已知触发。花粉相关时，回家换衣清洁、少接触高花粉时段，比盲买除敏设备更有目标。@0@1\n\n影响生活或药店方案无改善时，检查过敏、结构和鼻窦问题，再选[鼻炎药物](#/entry/nose-007)，不长期用快速通鼻掩盖。单侧不退、夹血或嗅觉持续变化另查；呼吸困难、哮喘加重及时求助。@0')
put('nose-007','过敏鼻塞规律用抗炎鼻喷，快速通鼻只短用',
'抗组胺药侧重痒喷嚏清涕，鼻用激素减局部炎症，不是增肌激素。持续过敏鼻塞可比较抗炎喷剂，规律使用并注意朝外侧喷；快速减充血剂长期用可能更堵，只按本品上限短用。孕期、心血管等情况和重复用药需先核。',
'抗组胺药如氯雷他定、西替利嗪可用于鼻痒喷嚏清涕，仍可能犯困；莫米松、氟替卡松等鼻用糖皮质激素主要抗局部炎症，持续过敏鼻塞可优先比较，不是健身激素。@0@1@2@3\n\n抗炎喷剂需规律用，不因一次未通自行加倍。轻擤、头稍前倾、朝鼻腔外侧避开鼻中隔喷，轻吸不猛吸到喉；规范仍不好就复查喷法、坚持与诊断，再讨论换药联合。@1\n\n羟甲唑啉、赛洛唑啉靠收血管快速通鼻，久用可反跳更堵。只短用数天：NHS现提醒不超过5天，中国本品若更短按其限制。孕期不自行用减充血剂；青光眼、重要心血管病、合用感冒药或频繁出血时先核。@4')
put('nose-004','洗鼻先保证安全用水，喷雾湿润不等于大水量冲洗',
'盐水喷雾主要湿润，冲洗器带走黏液；有鼻炎者可能受益，健康无困扰不必排毒式洗鼻。需要冲洗就用无菌蒸馏水或充分煮沸冷却水，按盐包和器具说明操作，盐包不杀菌。疼、耳压、反复血或症状加重就停，不追求高压更咸。',
'生理盐水是接近体液盐浓度的水溶液。喷雾偏湿润，大水量冲洗偏带走黏液刺激物；部分鼻炎可缓解，但不保证替代抗炎，也没可靠证据证明电动、高压、更咸普遍更好。@0@1\n\n洗手，按器具盐包配液，用蒸馏/无菌水或充分煮沸冷却水，自来水和普通饮用瓶水不自动合格。CDC列滚沸1分钟，约2000米以上3分钟再冷却；盐包不杀菌，不用纯水高压灌。用后清洁完全晾干。@2@0\n\n疼痛、耳压、反复出血或加重先停，术后或免疫低下按个人指导；洗后头痛、发热、呕吐或意识异常立即就医。无困扰不必每日洗鼻排毒。@2@0')
put('nose-006','流鼻血前倾捏鼻翼10至15分钟，不仰头塞深纸',
'坐下前倾，捏鼻翼软部连续10至15分钟，用嘴呼吸，不频繁松开看。量多、头伤后出血、晕弱或呼吸困难立即急诊；正确压迫仍不停也去急诊。反复出血或服抗凝药要查原因，不自行停药，止血后一天避免抠擤和剧烈活动。',
'**坐下，头身稍前倾，捏紧两侧鼻翼软部连续10至15分钟，用嘴呼吸。** 设计时，不频繁松开；不仰头、不只捏硬鼻梁，冰敷不能替代压迫。@0\n\n出血量大、吞血呕吐、头伤后流血、发晕虚弱或呼吸困难立即急诊，不必等满时间。正确压迫10至15分钟仍不停也去急诊，不塞更深纸巾等；反复、易淤青或用抗凝药查原因，不自行停药。@0\n\n止血后一天尽量不抠痂、猛擤、饮酒或剧烈活动。同处总结痂出血可需局部处理，不只归“上火”。@0')
put('nose-008','单侧鼻塞不退或嗅觉数周未恢复，安排耳鼻喉检查',
'单侧持续鼻塞、血性分泌物或面部麻痛，不能长期靠通鼻药遮住，也不等于一定是肿瘤。嗅觉数周不恢复也需查可处理原因，精油训练不保证恢复。闻不到时加强燃气报警和食物保存，伴急性视力眼周变化及时急诊。',
'持续单侧鼻塞可来自结构、炎症或占位，不等于癌症，但需要看清原因；反复血性分泌物、面部麻痛更不宜只靠通鼻喷剂。@0\n\n感冒、过敏、鼻息肉可使嗅觉变弱或闻错味，数周未恢复就检查。嗅觉训练可能帮部分人，不等于买精油必恢复，也不默认用补剂治疗。@1\n\n记录哪侧、多久、夹血、近期感染与用药，预约耳鼻喉。闻不到时不要凭鼻子判燃气和食物变质，核报警与保存；突然视力或明显眼周变化、严重急性不适及时急诊。@0@1')
put('nose-003','鼻头小点不一定是黑头，别挤到每孔都空',
'均匀浅平小点可能是正常皮脂丝，黑头则是堵塞形成的开口粉刺，两者不必一起挤。先温和清洁保湿，明确黑头再看面部护理的成分选择。红痛脱皮或破口就停刺激，不叠鼻贴、吸力和刷酸追求永久清空。',
'均匀、浅平的鼻头点可能是帮助油脂到达表面的正常皮脂丝；黑头是开口粉刺。都像小点，不等于都需挤出，鼻贴拉出东西也不代表病因解决。@0\n\n温和清洁保湿，不搓到涩。确有黑头，继续看[面部黑头护理](#/entry/skin-018)选择成分；不叠磨砂、酸、鼻贴和吸力。红痛、脱皮破口先停刺激，异常持久的小包斑点先确认病变，不当油粒挤。@0')
put('ears-005','听力突然下降立即求助，争取当天评估',
'突然一侧或双侧听不清、几天内明显变差，即使不痛也立即联系耳鼻喉或急诊，不先当耳屎。内耳性突发听损可能只是闷、鸣、晕，需要检查测听。伴面部无力、明显眩晕或头伤更要急诊，不靠手机测试或补剂拖延。',
'**突然听不清或几天内明显下降，立即联系耳鼻喉或急诊，争取当天评估。** 没有痛也不等；内耳等听觉结构的突发问题可能只像闷、耳鸣或头晕，易误当耳垢感冒。@0@1\n\n检查耳道鼓膜，排除堵塞积液，再用纯音测听区分类型；它测不同音高需多大声才能听到。确认为内耳性问题时可能需尽早讨论糖皮质激素等，不在家自购，也不等全部补充检查才首次求助。@0\n\n伴面无力、明显旋转晕或头伤后听损，急症处理；不拿手机测试正常否定变化，不先买营养神经用品。带手术药史，不自行停其他处方。@2')
put('ears-001','耳廓耳后用湿软布擦干净，工具不伸进耳道',
'洗脸洗澡时清洁耳廓凹槽、耳垂和耳后，再轻擦干，看得见的污垢去掉即可。耳垢有保护作用，棉签、采耳棒可能推深或擦伤，耳烛无已证实收益还有烧伤风险。厚痂不抠，反复痒裂渗液查皮炎，耳内痛流液或听力变则看耳科。',
'耳廓是外面的凹槽、耳垂及耳后褶皱，耳道是耳孔内通道。清洁范围不同，耳垢有保护作用、通常能自行外移，不需“整条掏空”。@0@4\n\n洗脸洗澡以湿软布轻擦外耳凹槽和耳后，再擦干；不把布角、指甲棉签往深处送、不灌水。儿童由照护者清外耳，新耳洞按[伤口护理](#/entry/ears-010)。@0@1\n\n厚痂不硬抠；反复痒、油屑、裂渗可能是皮炎，不是加力搓就好，皮肤科确认；耳内痛流液听力变看耳科。可视采耳也可推深擦伤，耳烛无已证实清垢收益且可烧伤留蜡。@2@3@4@5')
put('ears-002','耳垢确认堵塞再软化，穿孔手术史别自行滴洗',
'耳闷未必是耳垢，突然听不清先急诊。确认堵塞、鼓膜完整且无疼痛流液后，可按产品用软化剂；短暂更闷不代表应加量掏耳。有穿孔、置管、手术史或出血眩晕先看耳科，软化后仍堵也复查，不用厨房油或高压冲洗。',
'耳垢堵塞可使闷、听力下降，突然变化却不能先这么假定。正规软化剂帮助后续排出或取出，现有比较未证明某种商业配方普遍最好。@0@1\n\n确认堵塞、鼓膜完整且无疼痛流液等异常后，才按油基、碳酸氢钠等具体产品说明用；短时更闷不马上加量或伸工具。软化后仍堵或听力不恢复复查病因。@0@1\n\n穿孔、置管、手术史先问耳科，痛、流液、出血、明显晕不自滴油冲洗。专业吸引、器械或适当冲洗不同于家用高压；不用厨房食用油，也不把研究盐水对照当人人灌水许可。@2')
put('ears-003','游泳后排水擦干外耳，疼痒流液就停游检查',
'出水后偏头让水流出，轻拉耳垂、擦干外耳，不塞棉签吸水或挖耳垢。水仍留可用最低温风远距离吹。拉耳痛、耳痒流液可能是外耳道炎，应暂停游泳检查；干耳液不是治感染药，有穿孔置管等情况更不能自滴酒精配方。',
'外耳道炎又叫游泳耳，是耳道表面炎症感染，拉外耳或按耳口前小突起疼、痒、有分泌物可提供线索。没有不适时先排水干燥，不默认每次滴抗生素。@0@1\n\n偏头耳口朝下，轻拉耳垂，毛巾擦干外耳；水留着可用最低温最低风、保持距离吹，不往耳道塞棉签或先挖耳垢。反复可比较贴合泳塞。@0\n\n疼或流液停游检查，可能需针对滴药，不继续冲。干耳滴剂与抗菌治疗不同，穿孔、置管、已有炎症流液不自行用，也不自配酒精白醋。@0@1')
put('ears-004','耳机音量和时长一起减，强噪声另用听力防护',
'耳朵受声负担取决于多响和多久，音量滑块60%并非统一安全线。用设备暴露记录、限音和合适降噪减少越调越大；演唱会远离音箱并正确用防护耳塞。持续耳鸣或交谈费力查听力，突然听损走急诊，耳机不能修复已有损伤。',
'声音暴露同时看强度和时间：WHO用80分贝每周40小时、90分贝每周4小时说明越响可用时间越短，这是管理参考，不保证个人安全；手机60%滑块也不是固定声压。@0\n\n调到听清即可，不为盖住所有环境声不断加音量；设备有暴露记录、限音就用，合适降噪可帮助少加大声音。@0\n\n演唱会夜店远离音箱，正确用听力防护耳塞耳罩、安排安静休息；消费降噪不代替全部专业防护。持续耳鸣、交谈吃力查听力，突然下降[急诊](#/entry/ears-005)。@0')
put('ears-006','耳鸣持续影响生活先查听力，别先囤补剂',
'没有外界声源却听见鸣响叫耳鸣，持续加重或影响睡眠应查耳部和听力；搏动同步心跳尽快评估，伴突发听损等走急诊。长期目标可先减少困扰，按情况比较助听器、低音量环境声和行为治疗，补剂不代替这些。',
'耳鸣是无外界声源却听到嗡鸣铃声等，原因可涉及耳垢、感染、听损等。持续加重、影响睡眠先查耳部听力并带药单，不自行停药；随心跳搏动尽快评估，伴突发听损、面无力、明显晕或头伤按急症。@0\n\n长期治疗可追求少受困扰、睡得好，不只声音立刻归零。合并听损可谈助听器，低音量背景声有时有用；认知行为治疗帮助应对声音引起的困扰，不是说症状想出来的。@1\n\n无已知缺乏不把银杏维生素、营养神经或听毛细胞修复商品排在检查和有效应对前，声音用品也不必从最贵专机开始。@1')
put('ears-007','飞机下降时吞咽打哈欠，不为通耳猛烈鼓气',
'中耳靠咽鼓管与鼻咽通气，下降时没及时平压会闷痛。保持清醒、吞咽咀嚼或打哈欠，别为一声啪反复强鼓气。感冒耳鼻窦感染明显先评估飞行，落地后持续痛、流血流液或听力改变需检查，突然听损仍是急症。',
'中耳是鼓膜后的含气空间，咽鼓管连到鼻咽；飞机下降时通道打不开，内外压力不同可闷痛，外耳滴液不能简单替代中耳平压。@0@1\n\n下降保持清醒，间断吞咽、咀嚼、打哈欠；不反复猛烈鼓气，明显痛就停强尝试。感冒、耳或鼻窦感染仍明显时，先评估出行，不把快速通鼻当无风险许可。@0@1\n\n落地持续痛、流血流液或听力改变检查，突然明显听损[急诊](#/entry/ears-005)。既往手术鼓膜平衡问题按个人指导，潜水耳痛也不硬撑下潜。@2')
put('ears-009','打耳洞优先考虑耳垂，先问无菌操作和瘢痕风险',
'耳垂和软骨穿孔风险不同，软骨感染可能损伤耳形。到店核一次性无菌针、手套、复用灭菌与书面护理，别自己穿。自己或血亲有瘢痕疙瘩先咨询并考虑不穿；儿童还需能参与照顾、符合当地规定，不按一个年龄一律安排。',
'耳垂柔软，耳廓上部有软骨。软骨周围感染可影响供血、损伤耳形，所以首次优先考虑耳垂，但耳垂也不保证无感染。@0\n\n先问操作者培训、洗手换手套、全新无菌一次性针、复用器械高温灭菌及书面护理。可复用穿孔枪有灭菌和组织损伤问题，柜台整洁不能替代流程，不让朋友在家代劳。@1\n\n自己或血亲长过向伤口外持续长的瘢痕疙瘩，先看皮肤科并认真考虑不穿；普通旧疤明显不能单独诊断。儿童无统一适龄答案，考虑其参与决定和护理能力、监护及当地规定；慢性病或免疫治疗先与医护核适用。@2@3@4')
put('ears-010','新耳洞温和清洁，越来越肿热痛流脓当天就医',
'穿孔是伤口，洗手后按书面方案每天一至两次温和清洁、冲净轻吸干，不反复转拉和强消毒。耳垂常需六周或更久、软骨可能数月，不按日期随意拔换。感染加重当天看医护，疑感染先由医护决定取饰，嵌入不硬拔。',
'穿孔是待愈伤口，起初轻敏、少量淡液结痂，与越来越肿热痛、流脓不同。疑感染当天联系皮肤科、耳鼻喉或急诊；软骨尤其不拖，全身不适、发热发冷或快速扩展尽快急诊。@2@3\n\n洗手后按书面方案，通常每日一至两次，以正规伤口盐水或温和无香清洁剂加水轻洗冲净，一次性纸巾吸干，不塞孔、不抠痂；酒精双氧水强刺激可伤愈合皮肤，不高频加洗。@0@1@2\n\n不脏手摸转、不强转过痂，减少摩擦并避浸泡。耳垂常六周或更久、软骨可能数月，不统一到期换饰。疑感染先保留，由医护决定取下；嵌入不挤拔、不反复自涂抗生素盖变化。@0@1@4')
put('ears-008','耳饰一戴就痒先停可疑材质，反复发作查过敏原',
'耳针、耳扣和耳夹都可能接触致敏，镍是常见原因，黄金医用钢或低敏标签不保证合适。已愈合耳洞可先停可疑饰物，反复查斑贴。新洞肿热痛流脓要按感染检查，不自己硬拔；儿童还要查耳扣嵌入和小件脱落。',
'接触性皮炎是皮肤碰到某物后发炎，镍常见；不打洞、仅耳夹贴皮也可能过敏，耳针无镍不代表耳扣一样。@0\n\n已愈合处反复红痒起疹先停可疑耳饰或耳夹，记各部分材料；避开已知过敏原，不只看“低敏”“医用钢”或黄金名称。反复可在皮肤科做斑贴试验，按规定贴敷观察，不是耳后随擦一下便能排除。@1@0@2\n\n皮疹与感染可并存。新洞越来越肿热痛、脓液或发热发冷及时就医，取下由医护决定，不硬拔挤。儿童也查耳扣嵌入、小件脱落；止痒药年龄孕哺另核。@3')
put('ears-011','耳夹戴痛发麻就取下，轻耳饰也别长时压迫勾扯',
'耳夹虽不用穿孔，仍会压皮肤和接触过敏原。先试轻小平整、松紧可调款，痛麻发白破皮就取，不靠统一时长忍着戴。重耳坠和过紧耳扣也会伤耳；新洞和已愈洞的睡前处理不同，普通耳夹更不能拧紧当治疤夹。',
'耳夹靠夹持固定，无新穿刺但仍有压力和材质接触；没有人人通用的安全夹力时长。轻小、接触面平整、松紧可调更便于试，痛、麻、发白或破皮就取，不忍作适应。@0\n\n有洞耳饰也控重量，避粗糙针、过紧扣、勾扯长坠；已愈合洞睡前取下会压扯款，新洞按[护理](#/entry/ears-010)保留初饰、处理压迫，不混用。@1@2\n\n反复痒疹查镍等过敏；医用压力耳夹不同于普通装饰夹，凸起先诊断，不自行全天拧紧治疤。嵌入、撕裂或持续痛就医；婴幼儿不戴易脱落小夹以免吞吸。@3@4@0@5')

put('oral-018','牙痛脸肿发热尽快看牙，吞咽呼吸困难直接急诊',
'牙痛伴脸肿、发热或脓味可能是牙源性感染，暂时不痛也不代表好了。呼吸吞咽说话困难、大肿胀、明显张口受限或牵连眼睛视力，直接急诊。候诊温和清洁软食，止痛不加倍、不把阿司匹林贴牙龈，感染源仍需牙科处理。',
'**牙痛伴脸肿、发热或脓味尽快看牙；呼吸、吞咽、说话困难，大范围肿胀、明显张口受限，或累及眼睛视力，直接急诊。** 脓肿是感染积脓，不是忍一忍的上火，暂不痛也不代表消失。@0\n\n牙科要处理感染源，可能引流、根管清理牙内感染组织，或无法保留时拔牙；抗生素是否需要看感染情况，不能替代这些处理。@0\n\n候诊温和清洁、吃软食避刺激；适用止痛药按说明不加倍，不把阿司匹林贴牙龈以免灼伤。带过敏、免疫抑制和药单，不等常规洗牙预约。@1@2')
put('oral-013','冷热刺痛先查蛀牙裂纹，确认敏感再用抗敏牙膏',
'牙本质暴露会短暂刺痛，龋洞、牙裂或补牙松动也可能类似。反复、持续或单牙异常先查原因；确认敏感后用抗敏含氟膏、软刷轻清洁，少用磨蚀美白品。无效可讨论氟化物封闭修复，肿痛发热别只换牙膏。',
'牙本质在外层釉质下面，细小通道可把刺激传向牙髓，暴露时容易短促冷热痛；龋洞、牙裂和补牙松动也会痛，不能凭广告症状自诊。@0@1\n\n反复、持续或一颗牙特别异常先检查，区分缺损、退缩与感染。确认敏感为主后，再选抗敏用途含氟牙膏，按说明持续用、软刷轻清洁，减少磨蚀性美白。@0\n\n效果不足可谈局部氟化物、封闭或修复，不无限加购同类膏；美白明显刺激暂停复评，肿胀发热看[牙科急症](#/entry/oral-018)。@0')
put('oral-007','牙龈反复出血继续温和清洁，并检查牙周',
'刷牙清缝反复出血可能是炎症，不要因此跳过牙龈边缘。牙石刷不掉，专业检查需分牙龈炎与支持组织受损的牙周炎；口臭退缩、牙缝增大松动更应尽快看牙。复查维护按风险安排，套餐抛光不等于完整治疗。',
'牙菌斑是附着牙面的细菌膜，硬化形成的牙石刷不掉。炎症仅在牙龈与已损伤支持组织的牙周炎，治疗深度不同，必要时要测牙周袋、看片看骨支持。@1\n\n反复刷牙清缝出血，用合适刷毛与轻动作继续清，不跳过边缘；同时评估创伤和炎症。口臭、退缩、缝变大或松动尽快检查，专业清理可能需更深牙周治疗，不只是抛光。@0@1\n\n问清下次是常规检查还是牙周维护，间隔按风险与疗效，不等套餐券。吸烟、糖尿病和药物要告知；肿痛脓液发热走[感染分流](#/entry/oral-018)。@2')
put('oral-001','早晚用含氟牙膏刷全牙面，睡前那次别省',
'含氟牙膏帮助防龋，先把每天两次、每次约两分钟刷全做好，不靠天然无氟升级。成人常用1350—1500ppm，儿童用量另定；刷后吐泡沫，不立刻大量水漱，漱口水错开。已有洞或持续痛要修复，牙膏不能填回所有缺损。',
'氟帮助牙齿抵抗脱矿并支持早期再矿化，有直接防龋证据；天然无氟不是升级。成人可按标签选常用1350—1500ppm，ppm是百万分含量单位，更高浓度由牙科按风险决定。@0@1\n\n每天两次、每次约两分钟，保留睡前那次，固定顺序刷外内和咬合面、牙龈交界，不只门牙。吐掉多余泡沫，不立即大量水反复漱；漱口水另时用，牙缝[另清](#/entry/oral-003)。@0\n\n已有洞或持续痛要检查修复，再矿化不等于填回任意龋洞。儿童用量另定，不吞牙膏。@2')
put('oral-002','电动牙刷按操作能力选，不追震动参数和模式',
'手动能轻柔刷全且检查良好，不必因高级标签换电动。漏刷、计时困难或手不灵活时，电动可省操作，研究平均清洁指标有优势，但不是新机器未来少掉牙的保证。先看刷头、握持和更换便利，计时压力提醒比闲置模式实用。',
'电动牙刷帮助完成清洁动作，综述在平均菌斑、牙龈炎指标有优势，但研究较旧且有局限，不能换算成某新型号以后少掉几颗牙。@0@1\n\n手动已能轻刷全牙面、检查良好就可继续；总漏刷、难计时或手不灵活再比较电动。先看后牙够不够得到、刷毛、握持和持续换头是否方便。@0\n\n电动也不靠用力压，按刷头逐区操作，明显磨损更换。计时压力提醒按实际需要买，出血痛则查动作和[牙龈](#/entry/oral-007)，不是换硬毛解决。@0')
put('oral-003','每天清一次牙缝，窄缝牙线、宽缝选合适牙间刷',
'清牙缝不只挑食物，更要破坏附着菌斑。窄接触处牙线贴牙成C形轻移，宽缝可用合尺寸牙间刷，不硬塞弹伤。试验对部分牙龈炎改善有支持，长期保牙证据较少；难操作让牙科示范，出血持续检查，不据此停清洁。',
'牙刷难覆盖牙缝，牙线的任务也不只是挑肉丝，而是破坏牙面的菌斑。牙线或牙间刷加刷牙可改善部分牙龈炎指标，长期龋病保牙资料较少，不等于工具无用。@0@1@2\n\n每天一次：窄缝用牙线贴一侧成C形轻轻上下，再清另一侧，不锯着弹进牙龈；宽缝、退缩或矫治装置可比较合尺寸牙间刷，贴合不硬塞。@0@1\n\n难操作请牙科在自己的牙缝上演示；持续出血肿痛查[牙龈](#/entry/oral-007)。牙缝变大也可能是既有牙周问题，不能仅凭先后认定牙线撑大。@1')
put('oral-004','冲牙器可辅助清缝，不用冲出残渣代替清洁评估',
'冲牙器水流可降低牙套或手不灵活者的操作难度，但残渣量不是菌斑清除率。保留刷牙，从能耐受的水压按设备用；牙线牙间刷是否还需，结合牙龈和操作检查决定。短期炎症改善不代表全面胜过所有工具，术后按个别要求。',
'冲牙器用水流清洁周围，松散食物与黏附菌斑不同，冲出多少不能当清洁率。研究主要支持部分短期牙龈炎指标，不能说全面优于牙线，也不应说只有冲饭毫无价值。@0@1@2\n\n牙套难穿线或手部不便时可以比较，保留刷牙，从耐受设置按设备说明用，不靠最大压力证明效果。请牙科看菌斑、牙龈和操作，再定牙线或牙间刷需求。@0@1\n\n术后伤口按个别要求；持续出血松动肿痛查原因，不再加水压。@1')
put('oral-016','甜酸饮料别整天小口喝，无糖也要防酸蚀',
'蛀牙涉及菌斑用糖产酸，酸饮或胃酸还可直接侵蚀牙面，因此无糖不等于对牙无影响。减少全天小口接触，口渴以水为主；酸后或呕吐后先水漱，不马上用力刷。反酸、敏感或牙体变薄要查原因，修护商品不能长回已失牙体。',
'蛀牙涉及菌斑细菌用糖产酸；酸蚀可由饮料或胃酸直接溶解表面，无糖并不自动免酸挑战。@0@1\n\n少整下午小口喝甜酸饮，不在牙缝反复含漱，日常以水解渴。酸饮、很酸食物或呕吐后先水漱，不立即用力刷，之后仍软刷含氟；等待多久机构不一，不把某分钟当安全开关。@1\n\n反酸呕吐反复，或边缘薄、缺损、敏感，把饮食症状告知牙科及相关医生。已经丢失的牙体不能靠修护釉质产品长回，别只换牙膏。@1')
put('oral-005','漱口水按防龋、牙龈或口气目标选，不以辣为有效',
'漱口水是辅助，不能补上漏掉的刷牙和清缝。防龋可讨论含氟，部分牙龈口气问题看对应活性成分，氯己定等治疗按牙科疗程。口干敏感刺痛可比无酒精，辣不等于更好；含氟液与刷牙错开，不立刻冲掉牙膏保护。',
'漱口水可清新口气或辅助防龋、控菌斑，香味体验与治病不同，不能代替刷牙清牙缝。酒精有无也不等于整瓶功效，辣不证明有效。@0\n\n龋风险高时可谈含氟液；部分菌斑、牙龈或口气问题可比较西吡氯铵、特定精油等对应配方；术后特定治疗才按牙科要求用氯己定等，不追无限期杀菌。@0\n\n口干、黏膜敏感或酒精配方刺痛，优先比较无酒精。按中国具体标签，含氟漱口液与刷牙错开，不马上洗掉牙膏残氟；补牙和牙周治疗不能靠漱口替代。@0@1')
put('oral-006','氯己定按牙科疗程用，别长期压住牙龈出血',
'氯己定是辅助控菌斑炎症的抗菌剂，不会溶牙石，也不替代刷牙。按具体浓度频率疗程使用，注意染色，依方案与牙膏错开；约一周不改善或任何时候加重就联系牙科。不吞咽，也不用皮肤消毒品自配漱口液。',
'氯己定是抗菌剂，可用于部分治疗或术后辅助控菌斑炎症，但不会溶掉牙石、不能替代刷牙；无指征不把长期强消毒当日常。@0@1@2\n\n按牙科定的浓度频率疗程，不抄别人用量；可有牙齿染色，牙膏成分还可能影响作用，按方案错开，不立刻漱走牙膏保护。@1\n\n约一周未改善或任何时候加重就联系复评，不为了完成长疗程硬等。只用口腔专用、不吞，皮肤用消毒剂不能改作漱口。@1')
put('oral-019','换牙别硬拔乳牙，后面新长的六龄齿也要刷',
'约六岁前后开始乳恒牙共存，六龄齿长在乳磨牙后、不等乳牙掉，也不会再换。别系线硬拔，双排牙或萌出空间疑问到牙科评估；乳牙坏了仍要治，不能等换。家长帮助刷到新后牙，窝沟封闭按风险讨论，不按同学进度自判异常。',
'替牙期是乳恒牙共存阶段，约六岁开始但有差异。六龄齿是第一恒磨牙，长在最后乳磨牙后、不等乳牙脱落，也不会再换。窝沟封闭用材料封深沟，保护相应牙面。@0@1@2\n\n不系线或硬拔未自然松动乳牙。双排下前牙先看松动、恒牙位置与空间，牙不松、疼肿或萌出有疑就诊，不自拔邻牙腾位。@1@3\n\n家长帮刷到新后牙，按牙医评估讨论封闭与随诊。乳牙还管咀嚼和保留位置，龋坏要治，早失可能影响后续萌出；不买加速换牙用品、不照同学换牙数定异常。@4')
put('oral-020','孩子最迟七岁首次正畸评估，不等于马上戴牙套',
'评估正畸与开始治疗不同。发现问题就查，AAO建议最迟七岁首次检查，不是中国法定时限或人人七岁戴套。多数全面矫治可等换牙后约十一二岁讨论，但地包天、早失和异常萌出等不一律等。要求方案说清现在治什么、等的利弊及后续。',
'正畸用受控力量调整排列咬合，也要看颌骨发育。AAO建议有问题就评估、首次最迟七岁；这是检查建议，不是中国法定期限，也不是人人立刻治疗，结果可为观察。@0\n\n多数全面矫治可在换牙后约十一二岁讨论，可能更晚；过渡门牙缝、轻度拥挤未必立即处理。地包天、乳牙早失、异常萌出和明显咬合问题则不能一律等换完。@1@2\n\n青少年排不齐、咀嚼清洁困难就带具体困扰检查，问现在解决什么、等的利弊、是否还需第二阶段。不按“十八岁前必须做完”赶套餐，也不凭自拍决定。@0@3')
put('oral-021','孩子地包天尽早评估，成人先分牙齿与骨骼问题',
'下牙包上牙可能来自倾斜、咬合前移或颌骨关系，外观相似处理不同。孩子发现就评估，不等换完牙；早治不能保证将来不复发或不手术。成人也可改善，但明显骨性差异未必单靠牙套，手术与否需完整诊断。',
'地包天通常指下门牙包上门牙，可由牙倾斜、咬合干扰下颌前移或颌骨大小关系造成，不凭下巴照片判骨性。孩子发现就约儿童口腔或正畸，不等换完。@0@1\n\n牙位或功能前移适合时可早纠正，生长期骨骼问题可能谈生长引导；后续下颌生长仍不确定，需要跟踪，不能保证一次后不复发或一定免手术。@0\n\n成人也可处理，但牙移动有边界，明显骨差可需正畸与颌面外科联合评估正颌——手术调颌骨、通常配合正畸。是否手术看诊断目标，不因地包天三个字决定，也不自行买装置。@1@2')
put('oral-012','成年仍可正畸，先稳牙周并谈长期保持',
'正畸不以十八岁为截止，但要看牙体牙周和剩余牙支持条件。固定托槽或透明牙套先按需要移动什么、能否执行清洁来选，透明也不能靠照片网购自行换片。主动矫治后牙还可能移动，开始前谈好保持器和复查，不信拆套即永久结束。',
'正畸用受控力量移动牙齿，成人仍可评估；牙周是支持牙的牙龈与骨等，活动性疾病先治，老年还要看剩牙和支持量，不是任何年龄都马上适合。@0@1\n\n固定牙套用托槽弓丝，透明矫治器是按方案更换的可摘塑料套。先看移动目标，再比清洁、效果可达与执行；透明也需检查、必要影像复诊，不只靠照片买整套或自行加速换片。@2@3\n\n保持器维持主动矫治后的牙位，可摘或固定，牙以后仍会移动。治疗前谈长期保持维护和复查，全天转夜间、能否停按方案，不信统一一年皆可停。@4')
put('oral-009','牙齿美白先查着色原因，别用酸和炭粉硬磨',
'去渍与漂白不同：清洁牙膏处理表面着色，过氧化物牙贴凝胶改变天然牙颜色，瓷贴面又是修复。先处理牙痛龋病牙龈炎，补牙冠不会一起白；按正规产品用量时间，不适暂停。柠檬醋和强磨粉可能伤牙，不凭泡沫黑粉判断有效。',
'清洁、去渍牙膏主要处理外源着色；过氧化氢或过氧化脲牙贴凝胶化学漂白天然牙。家用美白贴与[瓷贴面](#/entry/oral-010)不是一类。@0\n\n先查想改变的是表面、天然牙还是修复体。牙痛龋洞牙龈炎先治，树脂、冠、贴面不会随漂白同步变白，提前想色差。选正规明确成分方法，按标签不加量超时，敏感和牙龈刺激明显就暂停复评。@0\n\n不拿柠檬、醋、活性炭牙粉或油拔替代有依据方案；酸、强摩擦可能伤牙，黑粉和泡沫不是安全证据，也不单为颜色直接磨牙做冠。@0@1')
put('oral-010','做贴面牙冠前先比少磨牙方案，并考虑维修',
'贴面覆盖牙前表面，冠覆盖更多牙面，两者不同于家用美白贴。贴面常去除部分釉质，不可简单逆转；若只为颜色先比清洁漂白，缺损排列再分别看修复正畸。问清每牙为何要做、磨多少及崩裂松动后如何修换，不凭终身承诺下单。',
'瓷贴面固定在牙前表面，烤瓷或全瓷冠包覆更多牙面，不能和家用美白牙贴混同。贴面通常需去部分釉质，这个决定不易逆转。@0\n\n主要为颜色时先比清洁漂白等保留牙体方案；缺损、排列形态则问修复和正畸各解决什么。龋病、活动牙周病先治，要求逐牙说明必要性、磨除量和替代。@0\n\n贴面会崩裂、松动、磨损而需修补更换，磨牙和咬合也影响选择；把后续维护责任与负担一起考虑，不把终身保修当临床寿命或相信完全不伤牙。@0')
put('oral-011','智齿按疾病和位置决定拔留，不靠疼不疼或瘦脸',
'智齿是最里面的第三磨牙，没痛不等于没问题，也不是人人一长就该拔。检查反复炎症、龋病、邻牙与清洁条件，必要时影像；无问题可监测，造成疾病别长期靠漱口压症状。拔前谈神经等风险，肿痛发热张口困难及时处理。',
'智齿是最里面的第三磨牙，不能正常萌出叫阻生。看有无反复冠周炎、龋坏、脓肿、囊性或邻牙问题，以及位置、清洁功能；影像可帮判断，不凭没疼过认定无病。@0\n\n位置合适无问题可监测，不统一预防拔；有疾病则不长期靠漱口盖住。问拔除目的、保留随访和感染出血神经风险，下颌邻神经受损可能影响唇舌下巴感觉。@0\n\n急性肿痛、发热或张口困难尽快处理，呼吸吞咽受影响[急诊](#/entry/oral-018)。不把瘦脸当主要医学理由，妊娠、特殊用药病史预约时说明。')
put('oral-017','白天咬紧牙先提醒放松，晨起颌痛磨损就检查',
'磨牙症可在白天紧咬或夜里磨动，不能一听声音就认定有虫。先提醒上下牙别持续接触，晨起酸痛、磨平崩裂敏感需牙科评估，也说明打鼾和用药。牙垫可保护牙齿却未必治病因，不自行削牙、改咬合或停处方。',
'磨牙症可表现为清醒紧咬或睡眠磨牙，原因未必相同；压力、睡眠、酒精咖啡因和药物可能参与，不凭声音判断肠虫。@0\n\n白天设提醒，让上下牙不要一直接触。晨起颌痛、牙磨平、崩裂或敏感，带自己和同住者记录去牙科；检查牙体修复体、肌肉，必要时评估睡眠。@0\n\n合适牙垫能隔开保护，但不保证从此不磨；不自用工具削牙改咬合。明显打鼾呼吸暂停、药物线索一并说，不自行停处方。@0')
put('oral-022','恒牙缺失先评估能保留哪些牙，再比义齿桥和种植',
'缺牙不必按最贵最先进统一选，也别为全口种植跳过残牙评估。活动义齿可摘，固定桥靠邻牙，种植靠颌骨内种植体；分别比较支持、手术、清洁和长期复查。老年并非不能种，整体健康更关键，种好也不等于免维护。',
'活动义齿可自行摘，靠剩牙牙龈等支持；固定桥利用邻牙支撑、不能自取；种植修复把人工种植体放颌骨承托冠桥或义齿。贴面则贴在已有牙上，不补缺牙。@0@1@2@3\n\n先评估残牙能保留哪些，别为全口套餐先拔。按缺牙数位、邻牙、骨软组织、意愿与护理能力比较：活动义齿看适应摘戴，桥看邻牙处理与桥下清洁，种植看手术愈合与长期随访。@0@2@3\n\n老年也可能适合，生日本身不决定；未控疾病、吸烟、感染等先评估处理。种植会失败或再治，不免维护。青少年发育期缺牙另评估，疼肿松动先查因，不自定拔光。@4@5')
put('oral-023','活动假牙每天取下清洁，磨痛松动就调适',
'可摘假牙每天清洁，通常别戴着睡；即刻义齿等按医生另定。用软刷温和皂配凉水，牙膏磨料和热水可能伤假牙，存放浸泡按材料。真牙仍含氟刷，牙龈舌面也清；疼痛松动、红白斑伤口复查，不自己磨或靠胶越粘越多。',
'活动义齿可自行取下，与固定桥和种植修复不同；每天摘洗、通常睡时取下，刚拔牙即刻义齿等先按制作医生安排。@0@1\n\n软刷少量温和液皂后凉水冲净，专用清洁剂按材料标签；普通牙膏磨料、热水可损表面。垫毛巾或有水池上方防摔，用清洁容器存，干放保湿和泡液按材料，不统一一瓶泡。真牙仍含氟刷，牙龈舌轻清。@0@1\n\n磨痛松动、伤口或红白斑带假牙复查，不自打磨；没真牙也需查黏膜和适合度，黏附剂不能代替调适。照护者洗手，不自行拆固定修复。@1@2')

put('lips-001','嘴唇干裂用简单润唇膏，刺痛清凉不代表修护',
'普通干裂可用白凡士林等耐受封护，按干燥补涂，睡前再用；不必叠唇膜唇油整套。薄荷香味或丰唇产品若刺激就停，不靠越凉越有效判断。护理两三周不改善查原因，热痛肿胀或水疱不能只加厚润唇膏。',
'白凡士林等润唇软膏在表面封护，减少水分散失，主要解决普通干裂，不是排毒或治疗所有唇炎。@0@1\n\n干起皮而无明显热痛肿时，先选一款简单耐受品，白天按需补、睡前用，吃喝擦掉后再看需要。基础已舒服不叠唇膜精华。避开让自己刺痛的香味、薄荷、刺激丰唇品，烧灼痒或裂加重就停。@0\n\n两三周仍不好查[反复唇炎](#/entry/lips-004)；热痛肿、水疱另查病因，不继续加厚遮过去。')
put('lips-002','想舔嘴唇就改补涂，起皮别撕咬或磨掉',
'反复舔湿又干掉会延续刺激，看到干皮也不必全部清空。用耐受润唇品替代舔、咬、撕，涂前洗手、不共用接触唇部的用品。基础封护已改善，不必添夜间套装；口呼吸口干反复时也查原因，不把问题只归于自控力。',
'反复唾液润湿又干掉，会延续干燥刺激循环；撕咬、磨砂又可能留下痛的破口，目标不是一次清光皮屑。@0@1\n\n发现想舔就改补一款耐受润唇品，不手撕牙咬；涂前洗手、不共用直接接触唇部用品。唇膜唇油同样看封护舒适，不因名字多一层就必叠。@0@1\n\n刺痛红痒的丰唇去角质先停，不再用力。持续口呼吸或口干可令干裂反复，另看[口干](#/entry/oral-015)，不单靠忍住不舔归罪自己。')
put('lips-003','户外给嘴唇防晒，吃喝擦掉后及时补',
'脸部涂防晒不代表嘴唇已覆盖。可选自己耐受、广谱SPF30及以上防晒润唇产品，户外约两小时补，吃喝游泳或擦掉后按标签补。帽子遮阴一起用，普通唇彩有颜色不自动等于同样防护；唇疱疹防晒也不保证不复发。',
'嘴唇也受日晒。广谱防晒润唇不同于普通唇油唇彩，颜色不能自动证明防护；日晒可诱发部分唇疱疹，但防晒不是免复发保证。@0@1\n\n按AAD建议可选SPF30及以上、广谱且不刺激品，干裂时氧化锌或二氧化钛版本可比较，不必复杂配方。户外约两小时补，吃喝、游泳、擦掉后按标签重新安排。@0\n\n配合帽子遮阴，不靠一层覆盖全天。SPF较低非毫无作用，固定处持续粗糙破损应[检查](#/entry/lips-004)。@1')
put('lips-004','嘴唇反复红痒裂先停可疑用品，固定处久不愈就检查',
'唇炎不全因天气干，口红和润唇品也可能刺激或过敏，旧品也不能排除。先减到耐受简单封护，记录用品照片；两三周不改善、固定处粗糙出血或肿块应看皮肤科口腔黏膜科。别反复磨皮试新品或长期混涂激素抗菌膏。',
'反复红痒裂可涉及刺激或接触过敏，口红唇彩、润唇品等都有可能，长期用过没事不能排除。先停近期可疑品、去角质和刺激丰唇，仅保留明确耐受的简单封护。@0@1\n\n仍反复时带开始时间、习惯、包装成分和照片就诊，分接触性唇炎、感染或其他病变。斑贴试验是专业受控贴敷、分时观察过敏原，不是在破唇轮试几十种。@0@2\n\n普通护理两三周无改善，或固定处长期粗糙、破损出血、肿块就查，不等于已诊断癌。热痛肿或成簇水疱另评估；不自长期混涂激素抗菌抗真菌。@1@3@4')
put('lips-005','唇边刺痒起成簇水疱，早谈抗病毒并避免传播',
'唇疱疹常先刺痒灼热再起成簇水疱，与口内溃疡不同。熟悉的确诊复发可在前驱期尽早讨论抗病毒，严重频繁者评估口服。从前驱到愈合都避亲吻口交、不共用品，尤其不吻婴儿；眼附近受累或十天未开始恢复需就医。',
'唇疱疹常由单纯疱疹病毒引起，先刺痒灼热再成簇水疱，与[口腔溃疡](#/entry/oral-014)不同。确诊且熟悉的复发，可早在前驱期讨论阿昔洛韦、喷昔洛韦等，严重频繁时评估口服，具体药按当地个人方案。@0@1\n\n前驱期到完全愈合都可传播：不亲吻口交，尤其不吻婴儿，触后洗手、不共唇用品。别挤水疱；贴片遮盖可带来保护外观，不代替抗病毒，家用光疗不足以作首选。@0\n\n眼附近、明显痛或大片、免疫受影响及时就医，十天左右仍未开始恢复或频发也复评。眼红痛怕光或视力异常按[急症](#/entry/eyes-005)，唇药不涂眼。@0@1')
put('lips-006','嘴角反复裂先减唾液刺激，别直接补维生素叠药',
'嘴角痛裂、潮湿发白结痂可能是口角炎，这只是表现，不是病因。先减舔和唾液积聚、用耐受封护；反复不愈查接触、牙或装置、感染及有需要的营养问题。抗真菌抗菌抗炎须对因，别自行全叠；先刺痒起簇疱另看唇疱疹。',
'口角炎指嘴角炎症表现，裂、痛、潮湿发白或结痂不能直接告诉病因。唾液积聚、舔或刺激可损皮，也可并发真菌细菌。@0\n\n先减少唾液刺激，耐受简单封护，不抠痂。反复不愈检查接触、牙和装置适配，按表现取样或查营养疾病；缺乏只是一类原因，有需要再补，药物不自行叠成总有一种有效。@0\n\n先刺痒后成簇疱看[唇疱疹](#/entry/lips-005)，热痛肿或破损扩展尽快查。不凭是否传染一句分准，不确定暂停共用品。@1@2')
put('oral-014','口腔溃疡先减刺激，同处超过三周未愈就检查',
'普通小溃疡常一两周恢复，先避烫酸辣硬食、查牙缘牙套摩擦，必要时询问口腔专用止痛抗炎。反复多发严重不默认缺维生素。同处三周不愈、变大出血或与过去不同需检查，异常明显不用等满三周，也不撒盐酒精消毒。',
'溃疡是口腔黏膜破损，与唇外成簇水疱不同；普通小溃疡常一两周恢复。摩擦、药物等原因很多，缺铁维生素不是唯一解释。@0\n\n避烫酸辣粗硬食，软刷，查尖牙缘、补牙边或牙套是否磨同处；易刺激可试不含SLS（月桂醇硫酸酯钠）的牙膏，但保留含氟防龋。痛碍进食可问口腔专用止痛抗炎，不撒盐酒精或改用皮肤药。@0\n\n同处超过三周、不像以往、变大或出血就查；伴其他部位溃疡或关节红肿也说。三周是检查提醒，不是任何异常都等满；反复严重按病史评估，不自停处方。@0')
put('oral-015','口干反复先查病因，再用无糖润口和防龋护理',
'唾液不足会影响吞咽并增加龋病感染风险，不只是口气不好。记录时段、眼干和用药变化，别自行停处方；可小口饮水、安全咀嚼者试无糖口香糖，或按需润口品。它们不保证恢复腺功能，牙科还需评估防龋，吞咽不安全不含硬糖。',
'唾液帮助吞咽、清除食物和保护牙，长期不足会增加蛀牙感染风险。可能与药物、唾液腺或其他疾病有关，不能只当喝水少。@0\n\n记录何时干、夜里是否重、是否眼干及新用药，交医护判断，不自停抗抑郁、降压等处方。小口补水，能安全咀嚼才试无糖口香糖；需时可选唾液替代润口，缓解不等于腺体恢复。@0\n\n少长期含糖果，漱口水可优先无酒精，牙科评估龋风险和氟护理。吞咽困难、不能安全咀嚼者不靠口香糖硬糖自护。@0@1')
put('oral-008','口臭先查牙龈龋齿口干，舌苔只轻柔清洁',
'薄荷或更辣漱口水只能短时改气味，不证明口腔病因消失。自护数周还持续，尤其出血牙痛松动，先查口腔。舌面附着不适可轻刷刮，不刮痛出血；长期治慢性口臭证据有限，不必人人买神器或追求无菌舌面。',
'菌斑、牙龈炎、龋齿与口干都可能参与口臭，香味盖住不代表处理了原因；嘴里有正常细菌，也不需追求无菌。@0\n\n先把刷牙清缝和实际病因处理好，自护数周仍持续或伴出血牙痛松动，先牙科，再按结果考虑别科。@0\n\n舌面附着不适可用软刷或舌刮从后向前轻清，不到痛出血；正常颜色纹理无需刮掉。NHS列轻柔清舌，ADA对长期预防改善慢性口臭保留，因此作可选尝试，不先买除臭神器。持续溃疡肿块异常红白斑也检查。@0@1')
put('skin-001','洗脸到干净舒服即可，紧绷起皮就减清洁补保湿',
'用温水指腹轻洗，不搓到发涩；通常每日约两次，明显出汗后按需清洁。洗后紧绷先减热水摩擦和刺激，再用耐受乳霜，不必水精华乳霜全叠。出油也不需洗光皮脂，温和后仍反复红痒屑应查病因，不只套屏障受损标签。',
'清洁去掉需要去掉的污物，保湿帮最外层皮肤留水，出油不等于要把皮脂全洗光。“氨基酸”“皂基”“修护”不能单独决定整瓶是否适合。@0@1\n\n温水指腹轻洗、轻擦干，通常每日约两次，明显出汗后再清洁。紧绷就先减热水摩擦和刺激洁面，再选耐受保湿：干可霜、怕厚可乳，不必全套层叠。@0@1\n\n温和仍反复红痒脱屑，停新增功效品，按[产品反应](#/entry/skin-005)、[玫瑰痤疮](#/entry/skin-016)或[脂溢性皮炎](#/entry/skin-017)检查，不用一个网络屏障标签解释一切。')
put('skin-002','按彩妆防晒的耐水性卸除，不默认每人洗两遍',
'卸妆任务是去掉当天用品，不是擦到棉片雪白。持妆彩妆耐水防晒按说明选合适卸品，普通洁面已能卸净且舒服就未必需另洗一遍。油膏水没有仅凭名字的冠军；温和溶解移除，灼痛红疹先停，反复带成分表检查。',
'卸妆油膏水是不同载体，目的都是移除目标用品，不靠名称决定肤质冠军。普通洁面若已完成任务，没有证据要求人人双重洗。@0@1\n\n睡前去彩妆，防水睫毛膏、持妆底妆、耐水防晒按说明选可卸除产品；先溶解或停留，再轻移，不清水反复擦或擦到棉片雪白。是否再洁面看用法残留和耐受。\n\n灼痛、眼周痒红、起疹先停可疑品，不换更强继续搓；持续反复带用品成分检查接触刺激过敏。偶尔漏卸不等于必然长痘，手摸不滑也不能保证防晒全去。@2')
put('skin-003','防晒涂全并按暴露补涂，再考虑抗老精华',
'先选能坚持的广谱SPF30及以上防晒，户外配衣帽遮阴；持续户外约两小时补，泳汗后按标签补。室内不必机械计时，底妆SPF也不保证涂量够。规律防晒有抗光老化试验支持，但不能消除所有斑皱或把研究比例叫年轻了多少。',
'广谱防晒兼顾UVA、UVB等紫外线，SPF不是放心晒的小时数。规律用有临床抗光老化证据：903名成人4.5年随机试验支持进展减少，不能翻成“年轻24%”。@0@2\n\n选可坚持的广谱SPF30及以上，暴露处涂匀涂全，户外配衣帽阴凉；泳汗用耐水款。持续户外通常约两小时补，泳汗摩擦后按标签，室内按实际暴露不机械计时。@0@1\n\n底妆标SPF不等于覆盖够；部分易色沉者可比较含氧化铁有色防晒的可见光保护。先补齐漏涂与难坚持，耐水不等于永久防水，也不按物理化学分安全高低。@1')
put('skin-004','面膜喷雾是可选舒适品，不替代保湿和治疗',
'基础保湿已舒服，不必为深层补水添整套面膜喷雾。喜欢短时肤感可以购买，但不据此承诺治痘重建胶原。保湿与刷酸面膜用途频率不同，按说明停留；刺痛灼红就取下洗去停用，不解释成排毒，反复干裂皮疹查原因。',
'面膜可带来短期肤感与放松，喷雾可即时舒适，这些不等于长期消皱、治痘或重建胶原。含保湿成分也不保证比合适乳霜更好。@0\n\n干燥先选耐受保湿，已稳定不必另加；喜欢体验可以自选。面膜按用途分保湿与酸/去角质，别同频率叠，停留按说明不越久越划算。@0\n\n刺痛灼热红痒取下洗去停用，不当吸收排毒；已有疗程新增酸或视黄醇先核重复刺激。反复干裂、疹、脱屑找原因，修护包装也不替代治疗。@0')
put('skin-019','斑痣变大变色或出血，先检查再美白点掉',
'新斑持续变、旧痣变大变色出血，或某颗与其他明显不同，先皮肤科检查，不当晒斑痘印。ABCDE帮助记变化，不需凑齐，小于六毫米也不能排除。照片只记录，性质未明别酸蚀点痣或激光破坏；稳定普通痣也不用全部切掉。',
'色斑和痣性质不同，新病变变化、旧痣变大变色出血或明显异于其他时，先检查，不能自动归晒斑痘印。@0@1\n\nABCDE提醒不对称、边缘不规、颜色不均、直径较大、持续演变；不是全部凑齐才查，六毫米也非排除线。自然光照片可记录，不能代替面诊必要检查。@0\n\n性质未明不用腐蚀点痣药、酸或美容激光去掉；明确后选观察、治疗或外观处理，稳定普通痣非都需切。年轻人也不必不分风险统一全身筛查，频率按人和病变。')
put('skin-021','淡斑先分晒斑痘印与黄褐斑，别套同一祛斑套餐',
'痘后色沉、晒斑和黄褐斑处理不同，变化出血先检查。黄褐斑先稳广谱防晒遮阳，部分可比较氧化铁有色防晒；进一步用药需监督，别自混氢醌维A酸激素长期涂。氨甲环酸不是美白补品，血栓史先评估，项目也不能保证永不反复。',
'晒斑、痘后色沉和黄褐斑是不同问题，后者常需长期维护。变化变色出血先[查性质](#/entry/skin-019)，痘后色沉看[痘印](#/entry/skin-007)，不套别人套餐。@0@1\n\n确认黄褐斑后稳住广谱SPF30及以上和遮阳，可比较含氧化铁有色防晒，避免反复刺激，需即时均匀可遮瑕。@2\n\n再谈受监督氢醌或对应复方、部分人壬二酸等替代，具体孕期适用另核，不自混氢醌维A酸激素长期涂；2026共识将基础防晒外用在前，激光主要留难治者。口服氨甲环酸是药、有血栓史先评估，不网购当保健美白，长期复诊看疗效刺激和维护。@3@1')
put('skin-005','新护肤品持续红痒灼痛就停，不硬扛建立耐受',
'持续红痒灼痛肿先停新产品、轻洗去，保留耐受基础；明显或不缓解就诊，眼唇急肿伴呼吸困难立即求助。普通新品可小范围试7至10天，但不保证不过敏。专业高浓度剥脱不是更猛爽肤水，不在家试浓度叠次数或中和。',
'持续红痒灼痛肿可能是刺激或其他反应，不能凭“刷酸后长疙瘩”叫排毒；酸的用途强度差很多，高浓度剥脱是造成可控损伤的专业处理。@0@2\n\n先停新产品、温和洗去，留耐受基础，不再叠修护硬压。明显或停后不缓解带成分就诊；眼唇迅速肿且呼吸困难等全身反应立即求助。@0\n\n普通新品可在前臂内侧按正常量频试7至10天、洗去型照洗，一次加一种；只能发现部分反应，非专业斑贴，也不保证将来不敏。专业剥脱勿自购试浓度、次数、中和，以免烧伤瘢痕。@1@2')
put('skin-006','粉刺小痘可规范外用，深痛结节或留疤尽早看皮肤科',
'粉刺小痘与深痛大包需要不同处理。阿达帕林等维A类疏堵，过氧化苯甲酰抗相关菌炎症，壬二酸水杨酸各有用途，不必一起上。常需数周、约6至8周评早期变化，刺激恶化留疤提前调整；备孕孕期避维A类，抗生素不长期单用。',
'痤疮涉及毛囊堵塞与炎症，不同皮损决定下一步。黑白头、少量小痘可规范外用；反复深痛结节、范围广、留疤或明显影响情绪，尽早皮肤科，不试完全部套装才去。@0@1\n\n阿达帕林等维A类疏堵兼处理部分炎症，过氧化苯甲酰针对相关细菌炎症、可干燥漂织物；壬二酸兼部分色沉，水杨酸偏粉刺。2024指南前两类较强推荐、后两类条件推荐，不等于全都一起用；核中国制剂和适用性。@2@0\n\n耐受方案约6至8周看早期变化，刺激、恶化、留疤提前复评。外用抗生素不长期单用，常考虑配过氧化苯甲酰；备孕孕期避外用及口服维A类，其他酸或替代也与产皮科确认范围，不自开口服处方。@2@3@4@5')
put('skin-018','黑头可治疗，正常皮脂丝不必挤空',
'鼻上均匀浅平灰黄点可能是正常皮脂丝，深色堵塞才可能是黑头粉刺。别拿针试或追求永久空毛孔；真正粉刺可按痤疮路径讨论水杨酸、外用维A类，孕备孕避维A。红痒脱屑先停刺激，持续隆起变化出血先确认性质。',
'黑头是毛囊开口处的开放性粉刺；皮脂丝是正常油脂通路，常为均匀细小平坦灰黄点，挤后重现不等于护理失败。看不准也别拿针试。@0\n\n确有黑白头、无严重红痛，可按[痤疮](#/entry/skin-006)讨论水杨酸或外用维A类，频繁不等于更好。阿达帕林是药，备孕孕期避；红痒脱屑先处理刺激，不继续叠酸。@1@2@3@4\n\n鼻贴撕拉吸挤只能暂带表面物，不能让正常通路消失，不反复强拉求零内容物。持续红肿痛痂停手检查，隆起、变化或出血先辨性质。@0')
put('skin-016','脸反复潮红灼热伴小疹，别只当敏感肌刷酸',
'中央面部反复红热、血丝小疹可能是玫瑰痤疮，不能靠照片确诊，也不等于普通痘。先减酸磨砂叠加功效，保留耐受清洁保湿防晒，记个人触发；炎性疹和血管泛红治疗不同。眼干眼睑不适要说，眼痛怕光或模糊及时眼科。',
'玫瑰痤疮是可复发炎症性皮肤病，可中央面部潮红、灼热、小疹血丝；名字有痤疮不等于普通青春痘，也非所有红脸都是角质层薄，需检查确认。@0\n\n先停刺激酸、磨砂和叠加功效，温和清洁、耐受保湿防晒，记录个人场景触发，不照网传清单取消所有热食运动。\n\n持续反复按主要表现治疗：炎性疹可涉及壬二酸、甲硝唑或伊维菌素等，血管泛红可能走相应光电路径，不先买去红套装。说明眼干睑不适；痛怕光、视力变化及时眼科。药物按诊断和中文说明，非自行处方。@0')

put('skin-017','鼻翼眉间红痒掉屑，别只当缺水厚敷面霜',
'这些位置反复红痒油屑可能是脂溢性皮炎，不证明没洗干净，也不能见脱屑就自诊真菌感染。温和清洁、停搓屑磨砂；确诊后再按需要抗真菌或短程抗炎。头皮洗剂不能照抄到脸，强激素不长期自行用，扩展疼痛渗出或无效复诊。',
'脂溢性皮炎是可能反复的炎症病，鼻翼、眉间、胡须区可红痒油屑；不等于不卫生，也不能仅凭脱皮排除其他皮炎或认定感染。@0\n\n温和清洁，停搓屑磨砂刺激品，保湿照顾干燥但不无限加厚。确认后可能用酮康唑等抗真菌，部分炎症需短程抗炎，不追越杀菌越好。@0\n\n头皮洗剂的时间频率不直接搬到脸、不入眼；不长期自用强激素或不明复方。反复扩展、疼渗或不改善，带药与护肤品复诊；抗真菌不代表脚气传染或需要无菌皮肤。@0')
put('skin-022','嘴周鼻旁反复小疹先查用药，不继续叠酸和激素',
'口周皮炎也可在鼻眼周起疹，和痤疮、刺激、玫瑰痤疮需区分。减新增和厚重叠涂，带药膏鼻喷吸入药及护肤清单检查；自行涂脸激素先停，处方先问开方者，不停哮喘鼻炎药。恢复可能数周至数月，反跳不证明应无限抹回。',
'口周皮炎是一类开口周围炎症疹，可在嘴鼻眼周伴干燥灼热脱屑，需与痤疮、接触反应和玫瑰痤疮分，不直接刷酸。@0@1\n\n减新增刺激与厚重叠涂，轻清不挤；带药膏、鼻喷吸入药和护肤清单就诊。自行抹脸的氢化可的松等先停，医生开的先联系调整，不把所有处方突然停掉。@0\n\n停脸部激素可暂反跳，抹回短时压住不代表适合长期。确诊按范围讨论外用口服，部分抗生素为控炎，不无限自涂。可需数周至数月，明显恶化或眼不适提前复评，眼痛怕光模糊及时眼科。@0@1')
put('skin-007','平坦痘印与凹凸痘疤分开治，先控制新痘',
'色素、红印和凹凸瘢痕不是同一问题，先控痘停挤，避免一边处理一边新增。色沉先防晒并按耐受讨论成分，红印和结构瘢痕另评估；激光、松解、填充解决的结构不同，精华不能保证填平全部痘坑，医美还要考虑色沉风险。',
'平坦颜色变化不同于凹凸瘢痕：褐印常是炎症后色沉，红印不全是黑色素。先控新痘、停挤，避免边淡边留。@0@1\n\n色沉先防晒，需时按耐受讨论壬二酸等，不叠多种美白刺激加深；红印久不退、性质不清或变样先查。@1\n\n痘坑按深浅形状肤色选，激光重塑表面，专业松解放开下方牵连，填充补体积；隆起瘢痕又不同。咨询要说清改哪种结构、幅度和色沉风险，不以轻微疤可外用推导精华填平所有坑。@0')
put('skin-008','治痘不先列禁食清单，饮食记录不能替代治疗',
'规律生活正常吃饭值得做，但普遍戒奶戒糖或抗糖丸还不是痤疮治疗处方。怀疑某食物时在护理稳定下逐项记录，不因一次改善定因果，也别无替代删整类食物。深痛留疤及时治疗，糖化机制或体外数值不等于成品人体抗老收益。',
'饮食可能影响部分痤疮，但2024指南认为不足以作普遍饮食治疗推荐；不是人人必须戒奶糖，也不是饮食绝无影响。糖化是糖与蛋白等反应，存在机制不证明抗糖丸能治痘淡纹。@0\n\n正常吃饭、规律生活，改善饮食可先减过量甜饮，不直接删水果、主食和全部奶。怀疑触发时保持护理用药相对稳定，一次改一因素记录，不以一次好转当因果，无替代不长期删整类食物。\n\n深痛、留疤或持续痘按[痤疮治疗](#/entry/skin-006)，不等生活百分百自律。保健品需对应成品人群临床结果，体外抗氧化或明星推荐不替代；也不自大剂量维生素A。@0')
put('skin-009','烟酰胺可按目标试，不为更高浓度自动加价',
'烟酰胺是维生素B3的一种形式，可用于保湿和部分外观改善，不代表一瓶包办控油祛痘美白。特定5%短期小试验有信号，却未证明10%更好。已有面霜含且舒服不必另叠精华；持续刺红痒就停，不以高浓度硬扛。',
'烟酰胺是维生素B3一种形式，可用于保湿和部分色沉细纹目标，不是成分一出现便包办控油、祛痘、美白。\n\n50名白人女性、12周半脸对照研究见特定5%配方部分指标改善，但样本小、时间短且作者有企业背景；未证明10%优于5%，也非全部精华通用结果。@0\n\n按自己目标选可耐受、不重复叠加的配方；面霜已有且舒服不必再买同成分精华。持续刺红痒按[产品反应](#/entry/skin-005)停评，真正痤疮或不明斑另走对应路径。')
put('skin-010','维A酸药与视黄醇分清，备孕孕期避维A类',
'药用维A酸可直接作用，化妆品视黄醇需转化，百分比不能横比。具体光老化目标可按耐受讨论，预防先做好防晒保湿。别同时新加维A、刷酸去角质，持续红痛裂先调整；备孕孕期避外用维A和视黄醇，哺乳或皮炎用药需另核。',
'维A酸tretinoin是直接作用受体的药，视黄醇需在皮肤内转化，稳定性配方用法影响效果；百分比不能横比，阿达帕林治痘也不等于人人最佳抗老。@0@1\n\n7项随机试验综述支持药用维A酸改善部分光老化，不为全部视黄醇精华背书。预防先稳防晒保湿，有细纹色素目标再讨论可耐受产品与药品适用。@1\n\n一次不新加多种维A、酸和去角质，持续灼痛大片红裂先停或调整，不以脱皮量计效果。备孕孕期避外用维A类，也不拿视黄醇当安全替代；哺乳、皮炎或同时治痘先核兼容，误用担忧记录产品问产科，不自行推断胎儿结局。@2@3@4')
put('skin-011','黑眼圈先分色素与阴影，眼霜不能填回凹陷',
'黑眼圈可来自色素、血管、眼袋凹陷阴影或皮炎，不全是熬夜。干就用耐受保湿，想即时遮盖可遮瑕，眼霜名字不证明更强。结构问题别靠揉眼按摩提拉；单侧持续变或肿要检查，眼周白粒别自己针挑，也不把普通去角质搬到眼皮。',
'黑眼圈可为皮肤颜色，也可能是眼袋凹陷阴影；遗传、血管、睡眠等参与，痒红屑还可为皮炎，不能全归熬夜。@0\n\n干燥先耐受眼周保湿，需即时外观可遮瑕；眼霜包装分类不证明胜过全部面霜，按具体目标刺激性选。反复肿痒屑先停新增眼妆护肤并检查，不加酸美白。@1@0\n\n凹陷和眼袋涉及结构，涂霜不能填回，强揉眼球拉皮也无已证实消袋效果。特别在意先评原因和项目风险；单侧持续变化检查。眼周白粒可含粟丘疹，并不全是油脂粉刺，不自行针挑挤，性质清楚后观察或专业去除。@0@2')
put('skin-012','胶原饮抗糖丸不列必需，购买前看成品人体证据',
'胶原补剂研究有正向结果，也有质量和资助偏倚；整体有益不保证高质量子组或个人肉眼有效。更晚发表的综述也未必检索更新。预算优先防晒保湿和疾病治疗，仍想买就接受不确定，核具体成品人群、结果持续和资金关系，不拿机制当疗效。',
'原料名、吸收率、体外抗糖抗氧化，不直接证明成品人体少皱；仪器指标变化也要看幅度、持续和是否在意。\n\n2025综述23项试验1474人，整体合并似有益，但高质量及作者定义非药企资助子组未见显著效果。2026另一综述有正向描述且多高偏倚，检索却止2023，不能只按发表年说更新。@0@1\n\n结论是不用列优先必需，不是全部被证伪。预算先给防晒保湿和治疗；仍买就按不确定可选消费，核具体产品人群临床结果和资金关系，抗糖机制不替代治痘。关节炎生活质量结果不搬成健康美容收益。@2@0@1')
put('skin-013','剃须先软化顺毛轻刮，反复起包就减少贴根刮',
'温水软化、配剃须品顺毛轻刮，别反复逆刮同处，痘不削平。红痛毛囊包反复时减少贴根和次数，可比较电动修剪；持续脓疱疼留印需区分倒生毛刺激等原因，别针挑。面部细毛按审美自选，眼下不必为保养剃净，眼缘不照搬刮脸法。',
'剃须是机械处理毛发，贴根反复刮可刺激；红包也可能与倒生毛炎症等有关，敏感刀头标签不能保证解决。@0\n\n温水湿润软化、用剃须膏凝胶、顺毛轻刮，使用中冲刀、清后干燥，不共用；有痘避开，不反复逆刮或削平痘。红刺激反复就减贴根和次数，可比较不过度贴肤的电修剪。@0\n\n持续脓疱痛或留印要查，不针挑挤或强去角质。细毛去留按妆效舒适，不是干净标准；皮肤正红痒或刺激治疗时别叠脱毛，眼皮眼缘不照搬普通刮脸。')
put('skin-020','底妆按遮盖耐受选，刷具洗净晾干不共用',
'粉底遮瑕能改善外观，不需要包办治痘填坑防晒。按轻薄全脸或局部遮色选，痘肌不致痘标签也不保证不长痘；红痒别为服帖刷酸磨砂。睡前温卸，刷具约7至10天清洗，明显污染提前，海绵另按材质，不将湿工具密闭收起。',
'底妆遮瑕主要改变当下外观，局部遮盖可少全脸厚涂；它不是治疗痤疮、填平疤或完成足量防晒的通用方案。\n\n按色号覆盖肤感选，易痘可比较不易堵孔标示但不保证个人适合，一次只换一项。正红痒屑先减刺激，不为服帖刷酸磨砂，治疗区按皮损用药调整，睡前温卸。@0@1\n\n刷具不共用，AAD约7至10天洗，频用或污染提前；洗刷毛冲净、平放晾干，不湿着塞密闭包。海绵其他工具按材质说明，产品变味变质或污染停用，眼妆另按眼睛章。@2')
put('skin-014','买红光面罩先看对应研究，射频微针不在家做',
'红光面罩部分研究有外观改善，但不同设备输出方案不能互借效果；先问对应机型、目标与长期使用要求。按时量护眼，光敏疾病用药先评估。射频微针是入皮释放能量的另一类操作，有严重风险警示、不供居家，不能拿便宜或无创名词忽略。',
'红光面罩用特定光照，射频微针让针入皮释放能量，两者不是同一技术。红光研究有部分外观改善，市售光源输出和方案却不同，机制不直接保证这台有效。@0\n\n买前问对应研究、目标和长期执行，按说明时间、眼防护，不延时叠仪器。光敏病、相关用药或不明疹先评估，海外监管标签不等于中国全部用途已批。@0\n\n2025 FDA报告射频微针烧伤、瘢痕、脂肪流失和神经损伤，明确不供居家；不因便宜或无创宣传尝试。报告数不算个人发生率，也不把风险套给全部LED或射频。@1')
put('skin-015','医美先定具体目标查资质，异常痛变色视力变化立即求助',
'斑、痘坑、纹路和凹陷对应不同结构，不由抗衰套餐包办。咨询带记录，核中国机构医生与产品用途，问风险和应急渠道。填充误入血管可坏死失明，异常痛、皮肤白灰蓝或视力变化立即医疗求助，卒中信号同样急救，不等复诊。',
'填充剂是注入组织改凹陷轮廓的医疗材料，不是涂玻尿酸的加强版；激光、填充、肉毒和微针目标不同，先说清要改色沉、坑、纹还是体积。\n\n带自然光照片和治疗记录，问为何选、预计改什么、次数和不适合情况。在中国查机构医疗许可范围、医生执业、实际操作者与产品设备部位用途及应急渠道，登记不能保证技术效果。@0\n\n填充误入血管可坏死失明：异常疼痛无需等剧痛，局部白灰蓝或视力变化立即求助；突发说话困难、面肢无力也立即急救。射频微针另有严重警示。不要自注、网购不明材料或拿美国许可代中国。外观不满不等于必须做。@1@2')
put('skin-023','肉毒注射只按表情纹目标评估，不当永久抗老',
'肉毒暂减目标肌肉收缩，可改善部分表情纹，与填凹陷不同。短期有随机研究支持，长期多周期仍有限，效果常数月；眼睑下垂、不对称和后续治疗要先谈。查医疗资质与药品，不自注或朋友代打；注后重影吞咽呼吸困难等立即求助。',
'肉毒毒素通过暂减目标肌肉收缩改善部分皱眉抬眉笑纹，不是填充，也不同时治斑、凹陷和所有松弛。@0\n\n综述支持部分面纹短期改善，也有眼睑下垂等风险，长期多周期结果有限；效果通常数月，按表情外观和维护意愿取舍，不同制剂单位、研究剂量不互换。@1@0\n\n核中国医疗机构医生、具体药品合法来源用途，不网购自注、不非医疗代打。说明用药孕哺既往反应，问不对称下垂应对。注后数小时至数周出现新重影模糊、下垂、吞咽或呼吸困难、明显无力，立即医疗求助并告知注射史，不等套餐复诊。@2@3')

def make_merges():
    merges=[]
    def merge(target,retired,title,summary,plain,benefit,evidence,notes,cost='',reason='同一读者决定下的重复步骤合成一篇，删除重复引言和免责声明。'):
        members=[byid[target],*[byid[i] for i in retired]]
        ids=list(dict.fromkeys(s for e in members for s in e['source_ids']))
        def refs(text):return re.sub(r'@([0-9]+)',lambda m:'[@'+ids[int(m.group(1))]+']',text)
        fields=dict(cost=refs(cost),plain=refs(plain),benefit=refs(benefit),evidence=refs(evidence),sources='；'.join('[@'+s+']' for s in ids),notes=refs(notes))
        audience_match=all(e['audience']['age_groups']==members[0]['audience']['age_groups'] and e['audience']['sexes']==members[0]['audience']['sexes'] for e in members)
        assert audience_match,(target,'audience differs')
        assert 60<=len(summary)<=140,(target,len(summary))
        assert set(re.findall(r'\[@([^\]]+)\]','\n'.join(fields.values())))==set(ids)
        merges.append(dict(target=target,retired=retired,title=title,summary=summary,fields=fields,reason=reason,age_sex_check=dict(same_age_groups=True,same_sexes=True,age_groups=members[0]['audience']['age_groups'],sexes=members[0]['audience']['sexes'],scope_notes=[e['audience']['scope_note'] for e in members]),original_plain_characters=sum(len(e['fields']['plain']) for e in members),merged_plain_characters=len(fields['plain']),clinical_review_status='not_clinically_reviewed'))
    merge('eyes-007',['eyes-015'],'眼干先选人工泪液，频繁使用优先比较无防腐剂',
        '普通干涩先试一款耐受水样人工泪液，频繁依赖或易刺激再优先无防腐剂并复评；夜间不足可讨论凝胶眼膏，油腺问题还需眼睑护理。去红不等于润滑，无防腐也要防污染；戴隐形允许性和开封弃置按标签，双氧水不能滴眼。',
        '人工泪液用来润滑眼表，常见玻璃酸钠、羧甲基纤维素、聚乙二醇等；防腐剂用于抑制瓶内污染。氧化型、可分解型仍是防腐体系，不能改叫无防腐剂。@0@1@7\n\n润滑可缓解相应干涩，但配方间及有无防腐剂的直接比较有限，不能保证所有人换后都更有效。长期反复用还要检查眼表与眼睑，不只增加滴药。@3@8\n\n白天偶发先选一款耐受水样品；夜间清晨仍不足，可检查后谈更持久、也更容易暂时模糊的凝胶眼膏，常放睡前。已确认睑板腺（眼皮供油腺）异常，可比较含脂质润滑并配眼睑护理，夜间不适不自动等于重度。@0@1@2\n\n偶用含防腐剂且舒服，不必一律换；长期高频、干眼较重或刺激明显，优先比较无防腐剂并复评。Mayo以每日超过4次作常见提醒，中国2024共识也提出相应选择，不是第5次开始有毒。@2@3@8\n\n戴隐形时另核允许性，无防腐标签本身不够。洗手、瓶口不碰眼，按包装开封弃置；其他疾病处方不自行替换，镜片双氧水消毒液不能滴眼。去红滴剂也非升级润滑，四氢唑啉等过用可增红；新用品后痛或视力异常停用并[及时就医](#/entry/eyes-005)。@6@5@9@4',
        '缓解部分干涩，按频率和耐受减少不必要刺激；复评也能发现仅靠补水不够的眼睑或眼表问题。@1@3@8',
        'B，人工泪液及防腐体系的直接比较有限；选择次序、包装防污染和用药安全为C，专业共识及机构指导。',
        '无防腐剂多剂量瓶依赖专用包装，单剂量支也按标签弃置。比较实际可用天数与剩液，不以每毫升便宜决定；频繁滴仍不好时继续走[干眼检查](#/entry/eyes-013)。',
        '单剂量小支可能有剩液，无防腐剂多剂量瓶需相应包装；按实际使用与弃置比较，不只比每毫升。')
    merge('lips-001',['lips-002'],'嘴唇干裂用耐受润唇膏，少舔、不撕皮',
        '普通干裂可用白凡士林等简单封护，按需补涂和睡前用；想舔时改补涂，皮屑不撕咬磨掉。清凉刺痛不代表修护，基础已改善无需再叠唇膜唇油。两三周不改善或热痛肿水疱就检查，口呼吸口干也可能使干裂反复。',
        '润唇软膏如白凡士林在表面封护、减少水分散失；反复唾液舔湿再干掉会延续刺激，撕咬磨砂又可能留下破口。它们都不是需要靠深层排毒解决的问题。@0@1\n\n普通干起皮、无明显热痛肿时，选一款简单耐受品，白天按干燥补、睡前用，吃喝擦掉后看需要；想舔改补涂，涂前洗手、不共用接触唇部用品。基础已舒服不必另买唇膜唇油夜间套装。@0@1\n\n薄荷香味、丰唇或去角质品若烧灼红痒先停，不靠越凉越有效，也不一次清空所有皮屑。两三周仍不好看[反复唇炎](#/entry/lips-004)，热痛肿、水疱另查；持续口呼吸或[口干](#/entry/oral-015)也要处理，不只怪自己忍不住舔。@0@1',
        '减轻普通干裂、减少舔咬撕造成的额外刺激；不能替代抗病毒或所有慢性唇炎的病因治疗。@0@1',
        'C，专业学会及公共医疗机构的封护和行为护理建议；不比较全部唇部成品疗效。',
        '长期口干、口呼吸或固定处破损，应向医护说明；嘴唇热痛肿或成簇水疱时，不只加厚封护。')
    merge('oral-005',['oral-006'],'漱口水按用途选，氯己定按疗程用、不代替刷牙',
        '漱口水能辅助防龋、牙龈护理或短时口气，先选目标再看成分，不以辣和杀菌口号判断。口干敏感可优先无酒精，含氟液与刷牙错开。氯己定仅按具体治疗疗程用，注意染色，约一周无改善或加重就复评，不会溶牙石也不替代清缝。',
        '漱口水是口腔护理的辅助，清新口气与治疗是不同目标，刷牙清缝不能省。氯己定是部分治疗或术后使用的抗菌剂，不会溶牙石。酒精有无也不等于全瓶功效，辣不代表有效。@0@2@3\n\n高龋风险可谈含氟液；部分菌斑牙龈口气问题可比较西吡氯铵、特定精油等对应配方；口干敏感或含酒精刺痛时优先无酒精。按中国产品标签，含氟漱口与刷牙错开，别立即洗掉牙膏残氟。@0@1\n\n氯己定按牙科给的浓度、频率和疗程，不将长期消毒设日常，也不抄别人用量。可使牙齿染色，牙膏成分可能影响作用，按具体方案错开。约一周不改善或任何时候加重，联系牙科，不为凑长疗程硬等；后续停用与处理按指导。@2\n\n只用口腔专用、不吞咽，皮肤消毒品不能改漱口；持续出血、牙石或牙周病需处理原因，不以香味或强消毒压住。@2@3',
        '让功能配方辅助相应目标，也保留短时清新体验；避免用长期强消毒掩盖需要牙科处理的疾病。@0@2',
        'C，协会用途分类和专业用药指导；不以单一成分证明所有成品相同有效。',
        '当地处方属性及用法看具体中文标签；不把其他国家药品权限或别人浓度疗程当成自己的方案。')
    (HERE/'head-merges.json').write_text(json.dumps(merges,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

def finish():
    result=[];audit=[]
    for e in original['entries']:
        if e['id'] not in updates:continue
        u=updates[e['id']]
        old_refs=set(re.findall(r'\[@([^\]]+)\]','\n'.join(e['fields'].values())))
        new_refs=set(re.findall(r'\[@([^\]]+)\]','\n'.join(u['fields'].values())))
        missing=old_refs-new_refs
        if missing:raise ValueError((e['id'],'lost refs',missing))
        if not 60<=len(u['summary'])<=140:raise ValueError((e['id'],'summary',len(u['summary'])))
        def numbers(text):
            text=re.sub(r'\[@[^\]]+\]','',text)
            text=re.sub(r'\]\([^)]*\)',']',text)
            return set(re.findall(r'\d+(?:\.\d+)?',text))
        removed=sorted(numbers(e['fields']['plain'])-numbers(u['fields']['plain']))
        if removed and (e['id']!='oral-005' or removed!=['99.9']):raise ValueError((e['id'],'clinical numeric loss',removed))
        record=dict(id=e['id'],all_original_fields_read=True,title_rewritten=u['title']!=e['title'],summary_rewritten=u['summary']!=e['summary'],plain_rewritten=u['fields']['plain']!=e['fields']['plain'],structure='概念与适用问题→证据和真正影响选择的边界→具体操作；紧急症状先行动',source_ids_preserved=sorted(old_refs),source_ids_lost=[],original_plain_characters=len(e['fields']['plain']),revised_plain_characters=len(u['fields']['plain']),original_plain_numeric_tokens=sorted(numbers(e['fields']['plain'])),revised_plain_numeric_tokens=sorted(numbers(u['fields']['plain'])),numbers_removed_for_review=[],numeric_review_resolution='原正文临床数字与研究年份保留；仅oral-005删除“杀菌99.9%”广告举例，非治疗阈值、剂量或研究结果。' if removed else '数字去除引用ID与内部链接编号后逐项对照，无临床数字丢失。',clinical_claims='未添加新医学结论；安全条件、关键时间、药物及地区边界在正文或保留字段中。')
        u['audit']=record;result.append(u);audit.append(record)
    (HERE/'head-rewrites.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    (HERE/'head-audit.json').write_text(json.dumps(dict(entries=audit,completed=len(result),expected=126,clinical_review_status='not_clinically_reviewed'),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('written',len(result), 'plain',sum(a['original_plain_characters'] for a in audit),'→',sum(a['revised_plain_characters'] for a in audit))
    make_merges()
if __name__=='__main__':finish()
